  Future<void> _handleLogin() async {
    setState(() {
      _loginErrors.clear();
    });

    final email = _loginEmailController.text.trim();
    final password = _loginPasswordController.text;

    bool hasErrors = false;

    if (email.isEmpty) {
      _loginErrors['email'] = 'Email is required';
      hasErrors = true;
    } else if (!_isValidEmail(email)) {
      _loginErrors['email'] = 'Enter a valid email address';
      hasErrors = true;
    }

    if (password.isEmpty) {
      _loginErrors['password'] = 'Password is required';
      hasErrors = true;
    }

    if (hasErrors) {
      setState(() {});
      return;
    }

    setState(() => _isLoggingIn = true);

    try {
      final isValid = await _validateCredentials(email, password);

      if (!isValid) {
        setState(() {
          _isLoggingIn = false;
          _loginErrors['email'] = 'Invalid email or password';
        });

        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Invalid email or password'),
            backgroundColor: Colors.red,
          ),
        );
        return;
      }

      final userData = await _getUser(email);

      if (userData == null) {
        setState(() => _isLoggingIn = false);
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('User data not found'),
            backgroundColor: Colors.red,
          ),
        );
        return;
      }

      print('=== LOGIN SUCCESSFUL ===');
      print('Full userData keys: ${userData.keys.toList()}');

      if (!userData.containsKey('registeredAt')) {

        userData['registeredAt'] = DateTime.now().toIso8601String();
        print('Added missing registeredAt field');
      }


      if (userData.containsKey('hotelName') ||
          userData.containsKey('totalRooms') ||
          userData.containsKey('roomDetails')) {
        print('Hotel data found in user data');

        userData['propertyType'] = 'hotel';
      } else if (userData.containsKey('villaName') ||
          (userData.containsKey('basicInfo') &&
              (userData['basicInfo'] as Map).containsKey('villaName'))) {
        print('Villa data found in user data');
        userData['propertyType'] = 'villa';
      } else if (userData.containsKey('apartmentName')) {
        print('Apartment data found in user data');
        userData['propertyType'] = 'apartment';
      } else if (userData.containsKey('resortName')) {
        print('Resort data found in user data');
        userData['propertyType'] = 'resort';
      }


      userData['lastLogin'] = DateTime.now().toIso8601String();
      await _saveUser(userData);

      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('is_logged_in', true);
      await prefs.setString('current_user_email', email.toLowerCase().trim());

      if (!mounted) return;

      setState(() => _isLoggingIn = false);
      _clearAllForms();

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Login successful!'),
          backgroundColor: Colors.green,
        ),
      );

      await Future.delayed(const Duration(milliseconds: 500));


      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (context) => OwnerDashboardScreen(
            userData: userData,
            userEmail: email.toLowerCase().trim(),
          ),
        ),
      );

      // Navigator.pushReplacement(
      //   context,
      //   MaterialPageRoute(
      //     builder: (context) => PropertiesScreen(
      //       userData: userData,
      //       userEmail: email.toLowerCase().trim(),
      //     ),
      //   ),
      // );

    } catch (e) {
      setState(() => _isLoggingIn = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Login error: ${e.toString()}'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

