}


class HotelRegistrationDetailsScreen extends StatefulWidget {
  final Map<String, dynamic> registrationData;

  const HotelRegistrationDetailsScreen({
    Key? key,
    required this.registrationData,
  }) : super(key: key);

  @override
  State<HotelRegistrationDetailsScreen> createState() =>
      _HotelRegistrationDetailsScreenState();
}


class _HotelRegistrationDetailsScreenState
    extends State<HotelRegistrationDetailsScreen>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  late Map<String, dynamic> _data;


  late Map<String, bool> _basicAmenities;
  late Map<String, bool> _hotelFacilities;
  late Map<String, bool> _foodServices;
  late Map<String, bool> _additionalAmenities;
  late List<String> _customAmenities;
  Map<String, bool> _editModes = {};

  late Map<String, bool> _policies;
  bool _isEditingPhone = false;
  late Map<String, bool> _priceEditModes; // For individual room price edits
  bool _isEditingTariffs = false; // For min/max tariff edits
  late TextEditingController _phoneController;

  final Color primaryColor = const Color(0xFFFF5F6D);
  final Color primaryLight = const Color(0xFFFF5F6D).withOpacity(0.1);
  final Color primarySoft = const Color(0xFFFF5F6D).withOpacity(0.05);
  final Color primaryMedium = const Color(0xFFFF5F6D).withOpacity(0.03);


  final Color darkText = const Color(0xFF1A1E2B);
  final Color mediumText = const Color(0xFF4A5568);
  final Color lightText = const Color(0xFF8E9AAB);
  final Color bgColor = const Color(0xFFF5F7FA);
  final Color cardColor = Colors.white;
  final Color borderColor = const Color(0xFFE9EDF2);
  final Color shadowColor = const Color(0xFF1A1E2B).withOpacity(0.03);

  @override
  void initState() {
    super.initState();
    _data = widget.registrationData;
    _tabController = TabController(length: 5, vsync: this);
    _phoneController = TextEditingController(text: _getUserPhone());

    _initializeAmenities();
    // Initialize price edit modes
    _priceEditModes = {};
    _isEditingTariffs = false;
  }

  void _initializeAmenities() {

    _editModes = {
      'basic': false,
      'hotel': false,
      'food': false,
      'additional': false,
      'custom': false,
    };
    // Initialize Basic Amenities
    if (_data['basicAmenities'] != null && _data['basicAmenities'] is Map) {
      _basicAmenities = Map<String, bool>.from(_data['basicAmenities']);
    } else {
      _basicAmenities = {
        'Free Wi-Fi': false,
        'Television': false,
        'Air Conditioning': false,
        'Attached Bathroom': false,
        'Hot Water': false,
        'Room Service': false,
      };
    }

    // Initialize Hotel Facilities
    if (_data['hotelFacilities'] != null && _data['hotelFacilities'] is Map) {
      _hotelFacilities = Map<String, bool>.from(_data['hotelFacilities']);
    } else {
      _hotelFacilities = {
        '24-Hour Front Desk': false,
        'Power Backup': false,
        'Lift / Elevator': false,
        'Parking Facility': false,
        'CCTV Security': false,
      };
    }

    // Initialize Food Services
    if (_data['foodServices'] != null && _data['foodServices'] is Map) {
      _foodServices = Map<String, bool>.from(_data['foodServices']);
    } else {
      _foodServices = {
        'Restaurant': false,
        'Complimentary Breakfast': false,
        'In-Room Dining': false,
        'Tea / Coffee Maker': false,
      };
    }

    // Initialize Additional Amenities
    if (_data['additionalAmenities'] != null && _data['additionalAmenities'] is Map) {
      _additionalAmenities = Map<String, bool>.from(_data['additionalAmenities']);
    } else {
      _additionalAmenities = {
        'Laundry Service': false,
        'Travel Desk': false,
        'Conference / Meeting Room': false,
        'Wheelchair Access': false,
      };
    }

    // Initialize Custom Amenities
    if (_data['customAmenities'] != null && _data['customAmenities'] is List) {
      _customAmenities = List<String>.from(_data['customAmenities']);
    } else {
      _customAmenities = [];
    }

    // Initialize Policies (if you have them in your data structure)
    if (_data['policies'] != null && _data['policies'] is Map) {
      _policies = Map<String, bool>.from(_data['policies']);
    } else {
      _policies = {};
    }
  }


  void _autoSaveAmenities() {
    _data['basicAmenities'] = Map<String, bool>.from(_basicAmenities);
    _data['hotelFacilities'] = Map<String, bool>.from(_hotelFacilities);
    _data['foodServices'] = Map<String, bool>.from(_foodServices);
    _data['additionalAmenities'] = Map<String, bool>.from(_additionalAmenities);
    _data['customAmenities'] = List<String>.from(_customAmenities);
    if (_policies.isNotEmpty) {
      _data['policies'] = Map<String, bool>.from(_policies);
    }
  }

  @override
  void dispose() {
    _phoneController.dispose();
    _tabController.dispose();
    super.dispose();
  }



  void _savePhoneChanges() {
    setState(() {
      // Update the phone number in data map
      if (_data.containsKey('phone')) {
        _data['phone'] = _phoneController.text;
      }
      if (_data.containsKey('mobileNumber')) {
        _data['mobileNumber'] = _phoneController.text;
      }

      _isEditingPhone = false;
    });

    // Optional: Show feedback
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Phone number updated successfully'),
        backgroundColor: primaryColor,
        duration: Duration(seconds: 2),
      ),
    );
  }

  Future<void> _pickAndUploadPhoto() async {
    try {
      final ImagePicker picker = ImagePicker();

      // Show dialog to choose between camera and gallery
      showModalBottomSheet(
        context: context,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
        ),
        builder: (BuildContext context) {
          return SafeArea(
            child: Wrap(
              children: [
                Padding(
                  padding: const EdgeInsets.all(16),
                  child: Text(
                    'Choose Photo',
                    style: TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.w600,
                      color: darkText,
                    ),
                  ),
                ),
                ListTile(
                  leading: Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: primarySoft,
                      shape: BoxShape.circle,
                    ),
                    child: Icon(Icons.photo_library, color: primaryColor),
                  ),
                  title: const Text('Gallery'),
                  onTap: () async {
                    Navigator.pop(context);
                    await _pickImageFromSource(ImageSource.gallery);
                  },
                ),
                ListTile(
                  leading: Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: primarySoft,
                      shape: BoxShape.circle,
                    ),
                    child: Icon(Icons.camera_alt, color: primaryColor),
                  ),
                  title: const Text('Camera'),
                  onTap: () async {
                    Navigator.pop(context);
                    await _pickImageFromSource(ImageSource.camera);
                  },
                ),
                const SizedBox(height: 10),
              ],
            ),
          );
        },
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error picking image: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  Future<void> _pickImageFromSource(ImageSource source) async {
    try {
      final ImagePicker picker = ImagePicker();
      final XFile? image = await picker.pickImage(
        source: source,
        maxWidth: 1000, // Resize image to save memory
        maxHeight: 1000,
        imageQuality: 85, // Compress image
      );

      if (image != null) {
        setState(() {
          _data['personPhotoInfo'] = {
            'uploaded': true,
            'name': image.name,
            'path': image.path,
          };
        });

        // Optional: Save to your backend/storage here

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Photo uploaded successfully'),
            backgroundColor: primaryColor,
            duration: Duration(seconds: 2),
          ),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error uploading photo: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }


  String _formatInteger(dynamic value) {
    if (value == null) return '';

    if (value is int) {
      return value.toString();
    }

    if (value is double) {
      return value.toInt().toString();
    }

    if (value is String) {
      // Try to parse as double first, then convert to int
      double? parsedDouble = double.tryParse(value);
      if (parsedDouble != null) {
        return parsedDouble.toInt().toString();
      }
      return value;
    }

    return value.toString();
  }


  String _formatPrice(dynamic value) {
    if (value == null) return '';

    if (value is double) {
      // Show .00 only if it has decimal places
      return value.toStringAsFixed(value.truncateToDouble() == value ? 0 : 2);
    }

    if (value is int) {
      return value.toString();
    }

    if (value is String) {
      double? parsed = double.tryParse(value);
      if (parsed != null) {
        return parsed.toStringAsFixed(
          parsed.truncateToDouble() == parsed ? 0 : 2,
        );
      }
      return value;
    }

    return value.toString();
  }


  String _getFormattedValue(dynamic value, {bool isPrice = false}) {
    if (value == null) return '';

    if (isPrice) {
      return _formatPrice(value);
    } else {
      return _formatInteger(value);
    }
  }

  String _getRegistrationId() {
    final hotelName = _data['hotelName']?.toString() ?? 'HOTEL';
    final timestamp = DateTime.now().millisecondsSinceEpoch
        .toString()
        .substring(8);
    final namePrefix = hotelName.length >= 3
        ? hotelName.substring(0, 3).toUpperCase()
        : hotelName.toUpperCase();
    return '$namePrefix-${timestamp}';
  }

  String _getUserFullName() {
    if (_data.containsKey('fullName') &&
        _data['fullName'].toString().isNotEmpty) {
      return _data['fullName'].toString();
    }
    if (_data.containsKey('ownerName') &&
        _data['ownerName'].toString().isNotEmpty) {
      return _data['ownerName'].toString();
    }
    return 'User';
  }

  String _getUserEmail() {
    return _data['email']?.toString() ?? 'Not provided';
  }

  String _getUserPhone() {
    if (_data.containsKey('phone')) {
      return _data['phone'].toString();
    }
    if (_data.containsKey('mobileNumber')) {
      return _data['mobileNumber'].toString();
    }
    return 'Not provided';
  }

  String _getHotelName() {
    return _data['hotelName']?.toString() ?? 'Hotel';
  }

  String _getHotelType() {
    return _data['hotelType']?.toString() ?? 'Normal Hotel';
  }

