  List<Widget> _buildRoomDetailsWithEditablePrices() {
    List<Widget> widgets = [];
    final roomDetails = _data['roomDetails'];
    final selectedRoomTypes = _data['selectedRoomTypes'];

    if (roomDetails is Map && selectedRoomTypes is Map) {
      selectedRoomTypes.forEach((type, isSelected) {
        if (isSelected == true && roomDetails.containsKey(type)) {
          final details = roomDetails[type];
          if (details is Map) {
            bool hasData = _hasValue(details['rooms']) ||
                _hasValue(details['occupancy']) ||
                _hasValue(details['price']);

            if (hasData) {
              String priceEditKey = 'price_$type';

              widgets.add(
                Container(
                  margin: const EdgeInsets.only(bottom: 12),
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: cardColor,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: borderColor),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // Header with Room Type and Edit button for price
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Row(
                            children: [
                              Container(
                                padding: const EdgeInsets.all(8),
                                decoration: BoxDecoration(
                                  color: primarySoft,
                                  borderRadius: BorderRadius.circular(10),
                                ),
                                child: Icon(
                                  Icons.hotel,
                                  size: 16,
                                  color: primaryColor,
                                ),
                              ),
                              const SizedBox(width: 12),
                              Text(
                                type.toString(),
                                style: TextStyle(
                                  fontSize: 14,
                                  fontWeight: FontWeight.w700,
                                  color: darkText,
                                ),
                              ),
                            ],
                          ),

                          // Edit Price Button (only if price exists)
                          if (_hasValue(details['price']))
                            _buildPriceEditButton(
                              isEditing: _priceEditModes[priceEditKey] ?? false,
                              onTap: () {
                                setState(() {
                                  // Toggle edit mode for this room's price
                                  _priceEditModes[priceEditKey] =
                                  !(_priceEditModes[priceEditKey] ?? false);
                                });
                              },
                            ),
                        ],
                      ),
                      const SizedBox(height: 12),

                      // Non-editable fields
                      if (_hasValue(details['rooms']))
                        _buildDetailRow('Number of Rooms', details['rooms']),

                      if (_hasValue(details['occupancy']))
                        _buildDetailRow('Max Occupancy', details['occupancy']),

                      if (details['ac'] != null)
                        _buildDetailRow(
                          'AC',
                          details['ac'] == true ? 'Yes' : 'No',
                        ),

                      // Price field - Editable
                      if (_hasValue(details['price']))
                        _buildEditablePriceField(
                          label: 'Price per Night',
                          value: details['price'],
                          roomType: type,
                          isEditing: _priceEditModes[priceEditKey] ?? false,
                          onSave: (newPrice) {
                            setState(() {
                              details['price'] = newPrice;
                              _priceEditModes[priceEditKey] = false;
                              _autoSaveRoomDetails();
                            });
                          },
                          onCancel: () {
                            setState(() {
                              _priceEditModes[priceEditKey] = false;
                            });
                          },
                        ),

                      if (details['extraBed'] != null)
                        _buildDetailRow(
                          'Extra Bed',
                          details['extraBed'] == true ? 'Yes' : 'No',
                        ),

                      if (details['extraBed'] == true &&
                          _hasValue(details['extraBedPrice']))
                        _buildDetailRow(
                          'Extra Bed Price',
                          details['extraBedPrice'],
                        ),
                    ],
                  ),
                ),
              );
            }
          }
        }
      });
    }
    return widgets;
  }

  Widget _buildEditableTariffCard() {
    // Create controllers for tariff fields
    final TextEditingController _minTariffController = TextEditingController(
      text: _data['minTariff']?.toString() ?? '',
    );
    final TextEditingController _maxTariffController = TextEditingController(
      text: _data['maxTariff']?.toString() ?? '',
    );

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: borderColor),
        boxShadow: [
          BoxShadow(
            color: shadowColor,
            blurRadius: 20,
            offset: const Offset(0, 8),
          ),
          BoxShadow(
            color: primaryColor.withOpacity(0.02),
            blurRadius: 10,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Header with Title and Edit Button
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: primarySoft,
                      borderRadius: BorderRadius.circular(14),
                    ),
                    child: Icon(Icons.attach_money, size: 18, color: primaryColor),
                  ),
                  const SizedBox(width: 12),
                  Text(
                    'Pricing Information',
                    style: TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.w700,
                      color: darkText,
                      letterSpacing: -0.3,
                    ),
                  ),
                ],
              ),

              // Edit/Finish Button for tariffs
              _buildPriceEditButton(
                isEditing: _isEditingTariffs,
                onTap: () {
                  setState(() {
                    if (_isEditingTariffs) {
                      // Save changes
                      _saveTariffChanges(
                        _minTariffController.text,
                        _maxTariffController.text,
                      );
                    }
                    _isEditingTariffs = !_isEditingTariffs;
                  });
                },
              ),
            ],
          ),
          const SizedBox(height: 16),

          // Tariff Fields
          if (_hasValue(_data['minTariff']))
            _isEditingTariffs
                ? _buildEditableTariffField(
              label: 'Min Tariff',
              controller: _minTariffController,
            )
                : _buildPriceRow('Min Tariff', _data['minTariff']),

          if (_hasValue(_data['maxTariff']))
            _isEditingTariffs
                ? _buildEditableTariffField(
              label: 'Max Tariff',
              controller: _maxTariffController,
            )
                : _buildPriceRow('Max Tariff', _data['maxTariff']),

          // Extra Bed status (non-editable)
          if (_data['extraBedAvailable'] != null)
            _buildStatusRow(
              'Extra Bed Available',
              _data['extraBedAvailable'] == true,
            ),

          // Save/Cancel buttons when editing
          if (_isEditingTariffs)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.end,
                children: [
                  TextButton(
                    onPressed: () {
                      setState(() {
                        _isEditingTariffs = false;
                        // Reset controllers to original values
                        _minTariffController.text = _data['minTariff']?.toString() ?? '';
                        _maxTariffController.text = _data['maxTariff']?.toString() ?? '';
                      });
                    },
                    style: TextButton.styleFrom(
                      foregroundColor: lightText,
                      padding: const EdgeInsets.symmetric(
                        horizontal: 16,
                        vertical: 8,
                      ),
                    ),
                    child: const Text('Cancel'),
                  ),
                  const SizedBox(width: 8),
                  ElevatedButton(
                    onPressed: () {
                      _saveTariffChanges(
                        _minTariffController.text,
                        _maxTariffController.text,
                      );
                      setState(() {
                        _isEditingTariffs = false;
                      });
                    },
                    style: ElevatedButton.styleFrom(
                      backgroundColor: primaryColor,
                      foregroundColor: Colors.white,
                      padding: const EdgeInsets.symmetric(
                        horizontal: 16,
                        vertical: 8,
                      ),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(20),
                      ),
                    ),
                    child: const Text('Save'),
                  ),
                ],
              ),
            ),
        ],
      ),
    );
  }

  // Helper method for price edit button
  Widget _buildPriceEditButton({
    required bool isEditing,
    required VoidCallback onTap,
  }) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(
          horizontal: 12,
          vertical: 6,
        ),
        decoration: BoxDecoration(
          color: isEditing ? primaryColor : primarySoft,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: isEditing ? Colors.transparent : primaryColor.withOpacity(0.2),
          ),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              isEditing ? Icons.check : Icons.edit,
              size: 14,
              color: isEditing ? Colors.white : primaryColor,
            ),
            const SizedBox(width: 4),
            Text(
              isEditing ? 'Done' : 'Edit Price',
              style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                color: isEditing ? Colors.white : primaryColor,
              ),
            ),
          ],
        ),
      ),
    );
  }

// Helper method for editable price field
  Widget _buildEditablePriceField({
    required String label,
    required dynamic value,
    required String roomType,
    required bool isEditing,
    required Function(double) onSave,
    required VoidCallback onCancel,
  }) {
    final TextEditingController _controller = TextEditingController(
      text: value?.toString() ?? '',
    );

    if (!isEditing) {
      return _buildDetailRow(label, value);
    }

    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: primarySoft,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: primaryColor),
      ),
      child: Column(
        children: [
          Row(
            children: [
              Expanded(
                flex: 3,
                child: Text(
                  label,
                  style: TextStyle(
                    fontSize: 12,
                    color: mediumText,
                    fontWeight: FontWeight.w500,
                  ),
                ),
              ),
              Expanded(
                flex: 4,
                child: TextField(
                  controller: _controller,
                  decoration: InputDecoration(
                    prefixText: '₹ ',
                    hintText: 'Enter price',
                    hintStyle: TextStyle(fontSize: 12, color: lightText),
                    border: InputBorder.none,
                    contentPadding: const EdgeInsets.symmetric(vertical: 4),
                    isDense: true,
                  ),
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w600,
                    color: darkText,
                  ),
                  textAlign: TextAlign.right,
                  keyboardType: TextInputType.number,
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Row(
            mainAxisAlignment: MainAxisAlignment.end,
            children: [
              TextButton(
                onPressed: onCancel,
                style: TextButton.styleFrom(
                  foregroundColor: lightText,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 4,
                  ),
                  minimumSize: Size.zero,
                ),
                child: const Text('Cancel', style: TextStyle(fontSize: 11)),
              ),
              const SizedBox(width: 8),
              ElevatedButton(
                onPressed: () {
                  double? newPrice = double.tryParse(_controller.text);
                  if (newPrice != null) {
                    onSave(newPrice);
                  }
                },
                style: ElevatedButton.styleFrom(
                  backgroundColor: primaryColor,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 4,
                  ),
                  minimumSize: Size.zero,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                ),
                child: const Text('Save', style: TextStyle(fontSize: 11)),
              ),
            ],
          ),
        ],
      ),
    );
  }

// Helper method for editable tariff field
