          ),
          const SizedBox(height: 16),

          // Add new custom amenity (only visible in edit mode)
          if (isEditMode)
            Column(
              children: [
                Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: _customController,
                        decoration: InputDecoration(
                          hintText: 'Enter new amenity...',
                          hintStyle: TextStyle(fontSize: 12, color: lightText),
                          contentPadding: const EdgeInsets.symmetric(
                            horizontal: 12,
                            vertical: 10,
                          ),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                            borderSide: BorderSide(color: borderColor),
                          ),
                          enabledBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                            borderSide: BorderSide(color: borderColor),
                          ),
                          focusedBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                            borderSide: BorderSide(color: primaryColor),
                          ),
                          filled: true,
                          fillColor: Colors.white,
                        ),
                      ),
                    ),
                    const SizedBox(width: 12),
                    SizedBox(
                      height: 45,
                      child: ElevatedButton(
                        onPressed: () {
                          if (_customController.text.trim().isNotEmpty) {
                            setState(() {
                              _customAmenities.add(_customController.text.trim());
                              _autoSaveAmenities();
                              _customController.clear();
                            });
                          }
                        },
                        style: ElevatedButton.styleFrom(
                          backgroundColor: primaryColor,
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        child: const Icon(Icons.add, color: Colors.white),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 16),
              ],
            ),

          // Display existing custom amenities
          if (_customAmenities.isNotEmpty) ...[
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: _customAmenities.asMap().entries.map((entry) {
                int index = entry.key;
                String amenity = entry.value;
                return Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color: isEditMode ? primarySoft : cardColor,
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color: isEditMode ? primaryColor.withOpacity(0.3) : borderColor,
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        amenity,
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: isEditMode ? primaryColor : darkText,
                        ),
                      ),
                      if (isEditMode) ...[
                        const SizedBox(width: 4),
                        GestureDetector(
                          onTap: () {
                            setState(() {
                              _customAmenities.removeAt(index);
                              _autoSaveAmenities();
                            });
                          },
                          child: Icon(
                            Icons.close,
                            size: 14,
                            color: Colors.red,
                          ),
                        ),
                      ],
                    ],
                  ),
                );
              }).toList(),
            ),
          ],

          // Empty state message for custom amenities
          if (_customAmenities.isEmpty && !isEditMode)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Text(
                'No custom amenities added',
                style: TextStyle(
                  fontSize: 12,
                  color: lightText,
                  fontStyle: FontStyle.italic,
                ),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildEditableAmenityCard({
    required String title,
    required IconData icon,
    required Map<String, bool> amenities,
    required Function(String, bool) onChanged,
  }) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: borderColor),
        boxShadow: [
          BoxShadow(
            color: shadowColor,
            blurRadius: 20,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: primarySoft,
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Icon(icon, size: 16, color: primaryColor),
              ),
              const SizedBox(width: 12),
              Text(
                title,
                style: TextStyle(
                  fontSize: 15,
                  fontWeight: FontWeight.w700,
                  color: darkText,
                  letterSpacing: -0.3,
                ),
              ),
              // const Padding(
              //   padding: EdgeInsets.only(left: 12),
              //   child: Text(
              //     '(Tap to toggle)',
              //     style: TextStyle(
              //       fontSize: 10,
              //       color: Color(0xFF8E9AAB),
              //       fontStyle: FontStyle.italic,
              //     ),
              //   ),
              // ),
            ],
          ),
          const SizedBox(height: 16),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: amenities.entries.map((entry) {
              bool isSelected = entry.value;
              return GestureDetector(
                onTap: () => onChanged(entry.key, !isSelected),
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 8,
                  ),
                  decoration: BoxDecoration(
                    gradient: isSelected
                        ? LinearGradient(
                      colors: [primaryColor, primaryColor.withOpacity(0.8)],
                    )
                        : null,
                    color: isSelected ? null : Colors.white,
                    borderRadius: BorderRadius.circular(25),
                    border: Border.all(
                      color: isSelected
                          ? Colors.transparent
                          : borderColor,
                      width: isSelected ? 0 : 1,
                    ),
                    boxShadow: isSelected
                        ? [
                      BoxShadow(
                        color: primaryColor.withOpacity(0.3),
                        blurRadius: 8,
                        offset: const Offset(0, 2),
                      ),
                    ]
                        : null,
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      if (isSelected)
                        const Icon(
                          Icons.check_circle,
                          size: 14,
                          color: Colors.white,
                        )
                      else
                        Icon(
                          Icons.circle_outlined,
                          size: 14,
                          color: lightText,
                        ),
                      const SizedBox(width: 6),
                      Text(
                        entry.key,
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: isSelected ? FontWeight.w600 : FontWeight.w500,
                          color: isSelected ? Colors.white : darkText,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }).toList(),
          ),
        ],
      ),
    );
  }

  Widget _buildGlassCard({
    required String title,
    required IconData icon,
    required List<Widget> children,
  }) {
    final filteredChildren = children.where((child) {
      if (child is SizedBox) return true;
      return child is Widget;
    }).toList();

    if (filteredChildren.isEmpty) return const SizedBox.shrink();

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: borderColor),
        boxShadow: [
          BoxShadow(
            color: shadowColor,
            blurRadius: 20,
            offset: const Offset(0, 8),
          ),
          BoxShadow(
            color: primaryColor.withOpacity(0.02),
            blurRadius: 10,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: primarySoft,
                  borderRadius: BorderRadius.circular(14),
                ),
                child: Icon(icon, size: 18, color: primaryColor),
              ),
              const SizedBox(width: 12),
              Text(
                title,
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  color: darkText,
                  letterSpacing: -0.3,
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          ...filteredChildren,
        ],
      ),
    );
  }

  Widget _buildInfoRow(String label, dynamic value) {
    if (value == null) return const SizedBox.shrink();

    String displayValue;

    // Check if this is a numeric field that needs special formatting
    if (label.contains('Year') ||
        label.contains('Rooms') ||
        label.contains('Occupancy') ||
        label == 'Total Rooms' ||
        label == 'Number of Rooms' ||
        label == 'Max Occupancy') {
      displayValue = _formatInteger(value);
    } else if (label.contains('Price') ||
        label.contains('Tariff') ||
        label.contains('Min') ||
        label.contains('Max')) {
      displayValue = '₹${_formatPrice(value)}';
    } else {
      displayValue = value.toString();
    }

    if (displayValue.isEmpty) return const SizedBox.shrink();

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 12),
      decoration: BoxDecoration(
        color: primaryMedium,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: primaryColor.withOpacity(0.05)),
      ),
      child: Row(
        children: [
          Expanded(
            flex: 3,
            child: Text(
              label,
              style: TextStyle(
                fontSize: 13,
                color: lightText,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
          Expanded(
            flex: 4,
            child: Text(
              displayValue,
              style: TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w600,
                color: darkText,
              ),
              textAlign: TextAlign.right,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildPriceRow(String label, dynamic value) {
    if (value == null) return const SizedBox.shrink();

    String displayValue = _formatPrice(value);
    if (displayValue.isEmpty) return const SizedBox.shrink();

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 12),
      decoration: BoxDecoration(
        color: primarySoft,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: primaryColor.withOpacity(0.15)),
      ),
      child: Row(
        children: [
          Expanded(
            flex: 3,
            child: Text(
              label,
              style: TextStyle(
                fontSize: 13,
                color: mediumText,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
          Expanded(
            flex: 4,
            child: Text(
              '₹$displayValue',
              style: TextStyle(
                fontSize: 14,
                fontWeight: FontWeight.w700,
                color: primaryColor,
              ),
              textAlign: TextAlign.right,
            ),
          ),
        ],
      ),
    );
  }

  // Status Row
  Widget _buildStatusRow(String label, bool value) {
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 12),
      decoration: BoxDecoration(
        color: value ? primarySoft : primaryMedium,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: value ? primaryColor.withOpacity(0.2) : borderColor,
        ),
      ),
      child: Row(
        children: [
          Expanded(
            flex: 3,
            child: Text(
              label,
              style: TextStyle(
                fontSize: 13,
                color: lightText,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
          Expanded(
            flex: 4,
            child: Row(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                Icon(
                  value ? Icons.check_circle : Icons.cancel,
                  size: 16,
                  color: value ? primaryColor : lightText,
                ),
                const SizedBox(width: 6),
                Text(
                  value ? 'Yes' : 'No',
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w600,
                    color: value ? primaryColor : lightText,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // Account Type Row
  Widget _buildAccountTypeRow(dynamic accountType) {
    if (accountType == null || accountType.toString().isEmpty) {
      return const SizedBox.shrink();
    }
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 12),
      decoration: BoxDecoration(
        color: primarySoft,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: primaryColor.withOpacity(0.15)),
      ),
      child: Row(
        children: [
          Expanded(
            flex: 3,
            child: Text(
              'Account Type',
              style: TextStyle(
                fontSize: 13,
                color: lightText,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
          Expanded(
            flex: 4,
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
              decoration: BoxDecoration(
                color: primaryColor.withOpacity(0.1),
                borderRadius: BorderRadius.circular(20),
              ),
              child: Text(
                accountType.toString(),
                style: TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w600,
                  color: primaryColor,
                ),
                textAlign: TextAlign.center,
              ),
            ),
          ),
        ],
      ),
    );
  }

  List<Widget> _buildLandlineNumbers(dynamic landlineNumbers) {
    List<Widget> widgets = [];
    if (landlineNumbers is List && landlineNumbers.isNotEmpty) {
      for (var i = 0; i < landlineNumbers.length; i++) {
        if (landlineNumbers[i].toString().isNotEmpty) {
          widgets.add(_buildInfoRow('Landline ${i + 1}', landlineNumbers[i]));
        }
      }
    }
    return widgets;
  }

  List<Widget> _buildRoomTypes() {
    List<Widget> widgets = [];
    final selectedRoomTypes = _data['selectedRoomTypes'];
    if (selectedRoomTypes is Map) {
      final selected = selectedRoomTypes.entries
          .where((e) => e.value == true)
          .map((e) => e.key)
          .toList();

      if (selected.isNotEmpty) {
        widgets.add(
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: Wrap(
              spacing: 8,
              runSpacing: 8,
              children: selected
                  .map(
                    (type) => Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: [primaryColor, primaryColor.withOpacity(0.8)],
                    ),
                    borderRadius: BorderRadius.circular(20),
                    boxShadow: [
                      BoxShadow(
                        color: primaryColor.withOpacity(0.2),
                        blurRadius: 8,
                        offset: const Offset(0, 2),
                      ),
                    ],
                  ),
                  child: Text(
                    type.toString(),
                    style: const TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: Colors.white,
                    ),
                  ),
                ),
              )
                  .toList(),
            ),
          ),
        );
      }
    }
    return widgets;
  }

  List<Widget> _buildRoomDetails() {
    List<Widget> widgets = [];
    final roomDetails = _data['roomDetails'];
    final selectedRoomTypes = _data['selectedRoomTypes'];

    if (roomDetails is Map && selectedRoomTypes is Map) {
      selectedRoomTypes.forEach((type, isSelected) {
        if (isSelected == true && roomDetails.containsKey(type)) {
          final details = roomDetails[type];
          if (details is Map) {
            bool hasData =
                _hasValue(details['rooms']) ||
                    _hasValue(details['occupancy']) ||
                    _hasValue(details['price']);

            if (hasData) {
              widgets.add(
                Container(
                  margin: const EdgeInsets.only(bottom: 12),
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: cardColor,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: borderColor),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            padding: const EdgeInsets.all(8),
                            decoration: BoxDecoration(
                              color: primarySoft,
                              borderRadius: BorderRadius.circular(10),
                            ),
                            child: Icon(
                              Icons.hotel,
                              size: 16,
                              color: primaryColor,
                            ),
                          ),
                          const SizedBox(width: 12),
                          Text(
                            type.toString(),
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w700,
                              color: darkText,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),

                      if (_hasValue(details['rooms']))
                        _buildDetailRow('Number of Rooms', details['rooms']),

                      if (_hasValue(details['occupancy']))
                        _buildDetailRow('Max Occupancy', details['occupancy']),

                      if (details['ac'] != null)
                        _buildDetailRow(
                          'AC',
                          details['ac'] == true ? 'Yes' : 'No',
                        ),

                      if (_hasValue(details['price']))
                        _buildDetailRow('Price per Night', details['price']),

                      if (details['extraBed'] != null)
                        _buildDetailRow(
                          'Extra Bed',
                          details['extraBed'] == true ? 'Yes' : 'No',
                        ),

                      if (details['extraBed'] == true &&
                          _hasValue(details['extraBedPrice']))
                        _buildDetailRow(
                          'Extra Bed Price',
                          details['extraBedPrice'],
                        ),
                    ],
                  ),
                ),
              );
            }
          }
        }
      });
    }
    return widgets;
  }

  bool _hasValue(dynamic value) {
    if (value == null) return false;
    if (value is String && value.isEmpty) return false;
    if (value is num && value == 0) return true;
    return true;
  }

  Widget _buildDetailRow(String label, dynamic value) {
    if (value == null) return const SizedBox.shrink();

    String displayValue;

    if (label.contains('Rooms') || label.contains('Occupancy')) {
      displayValue = _formatInteger(value);
    } else if (label.contains('Price') || label.contains('Tariff')) {
      displayValue = '₹${_formatPrice(value)}';
    } else if (label == 'AC' || label == 'Extra Bed') {
      displayValue = value == true ? 'Yes' : 'No';
    } else {
      displayValue = value.toString();
    }

    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(label, style: TextStyle(fontSize: 12, color: lightText)),
          Text(
            displayValue,
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w600,
              color: darkText,
            ),
          ),
        ],
      ),
    );
  }

  // Step 5: Legal & Bank Details
  Widget _buildStep5() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          _buildGlassCard(
            title: 'Legal Details',
            icon: Icons.gavel,
            children: [
              _buildInfoRow('GST Number', _data['gstNumber']),
              _buildInfoRow('FSSAI License', _data['fssaiLicense']),
              _buildInfoRow('Trade License', _data['tradeLicense']),
              _buildInfoRow('Aadhar Number', _data['aadharNumber']),
              _buildInfoRow('PAN Number', _data['panNumber']),
            ],
          ),
          const SizedBox(height: 16),
          _buildGlassCard(
            title: 'Bank Details',
            icon: Icons.account_balance,
            children: [
              _buildInfoRow('Account Holder', _data['accountHolderName']),
              _buildInfoRow('Bank Name', _data['bankName']),
              _buildInfoRow(
                'Account Number',
                _data['accountNumber']?.toString() ?? '',
              ),
              _buildInfoRow('IFSC Code', _data['ifscCode']),
              _buildInfoRow('Branch', _data['branch']),
              _buildAccountTypeRow(_data['accountType']),
            ],
          ),
          const SizedBox(height: 16),
          _buildGlassCard(
            title: 'Uploaded Documents',
            icon: Icons.folder,
            children: _buildUploadedDocuments(),
          ),
        ],
      ),
    );
  }

  List<Widget> _buildUploadedDocuments() {
    List<Widget> widgets = [];
    final uploadedFiles = _data['uploadedFiles'];

    if (uploadedFiles is Map) {
      uploadedFiles.forEach((key, value) {
        if (value is Map && value['uploaded'] == true) {
          widgets.add(
            Container(
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: primarySoft,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: primaryColor.withOpacity(0.15)),
              ),
              child: Row(
                children: [
                  Icon(Icons.check_circle, size: 16, color: primaryColor),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          key,
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w600,
                            color: darkText,
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          'Uploaded successfully',
                          style: TextStyle(fontSize: 11, color: lightText),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          );
        }
      });
    }

    return widgets;
  }

  Widget _buildPhotoTile(Map<String, dynamic> photoInfo) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: borderColor),
      ),
      child: Row(
        children: [
          Container(
            width: 50,
            height: 50,
            decoration: BoxDecoration(
              gradient: LinearGradient(
                colors: [primaryColor, primaryColor.withOpacity(0.7)],
              ),
              borderRadius: BorderRadius.circular(14),
            ),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(14),
              child: photoInfo['path'] != null
                  ? Image.file(
                File(photoInfo['path']),
                fit: BoxFit.cover,
              )
                  : const Center(
                child: Icon(Icons.photo_camera, color: Colors.white, size: 24),
              ),
            ),
          ),
          const SizedBox(width: 16),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'Profile Photo',
                  style: TextStyle(fontSize: 14, fontWeight: FontWeight.w600),
                ),
                const SizedBox(height: 2),
                Text(
                  photoInfo['name'] ?? 'Uploaded successfully',
                  style: TextStyle(fontSize: 12, color: lightText),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ],
            ),
          ),
          Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: primarySoft,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Icon(Icons.check_circle, size: 18, color: primaryColor),
          ),
        ],
      ),
    );
  }
}


class TwoStarHotelDetailsScreen extends StatefulWidget {
  final Map<String, dynamic> registrationData;

  const TwoStarHotelDetailsScreen({super.key, required this.registrationData});

  @override
  State<TwoStarHotelDetailsScreen> createState() =>
      _TwoStarHotelDetailsScreenState();
}


class _TwoStarHotelDetailsScreenState extends State<TwoStarHotelDetailsScreen>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  late Map<String, dynamic> _data;

  // Editable state for amenities - ALWAYS EDITABLE
  late Map<String, bool> _roomAmenities;
  late Map<String, bool> _hotelFacilities;
  late Map<String, bool> _foodServices;
  late Map<String, bool> _guestServices;
  late List<String> _customAmenities;
  Map<String, bool> _editModes = {};

  bool _isEditingPhone = false;
  late TextEditingController _phoneController;
// Add these state variables
  late Map<String, bool> _editPriceModes;
  late TextEditingController _priceController;
  late TextEditingController _minTariffController;
  late TextEditingController _maxTariffController;

  late String _checkInTime;
  late String _checkOutTime;
  late bool _coupleFriendly;
  late bool _petsAllowed;
  late String? _idProofRequired;

  // Add controllers for time pickers
  final TextEditingController _checkInController = TextEditingController();
  final TextEditingController _checkOutController = TextEditingController();

  // Time options for dropdown
  final List<Map<String, String>> _timeOptions24Hour = [
    {'value': '00:00', 'display': '12:00 AM'},
    {'value': '01:00', 'display': '01:00 AM'},
