    // Initialize edit modes for price sections
    _editPriceModes = {
      'roomPrice': false,
      'tariffRange': false,
    };

    // Initialize price controllers
    _priceController = TextEditingController();
    _minTariffController = TextEditingController();
    _maxTariffController = TextEditingController();
    // Initialize editable amenities from registration data
    _initializeAmenities();

    // Initialize editable policies from registration data
    _initializePolicies();

    _initializePriceValues();
