  void _initializePriceValues() {
    // Initialize price per night from room details
    if (_data['roomDetails'] != null && _data['roomDetails'] is Map) {
      final roomDetails = _data['roomDetails'];
      final selectedRoomTypes = _data['selectedRoomTypes'];

      if (selectedRoomTypes is Map && roomDetails is Map) {
        // Find the first selected room type to get its price
        for (var entry in selectedRoomTypes.entries) {
          if (entry.value == true && roomDetails.containsKey(entry.key)) {
            final details = roomDetails[entry.key];
            if (details is Map && details.containsKey('price')) {
              _priceController.text = details['price'].toString();
              break;
            }
          }
        }
      }
    }

    // Initialize min/max tariff
    if (_data['minTariff'] != null) {
      _minTariffController.text = _data['minTariff'].toString();
    }
    if (_data['maxTariff'] != null) {
      _maxTariffController.text = _data['maxTariff'].toString();
    }
  }

