// Update the save method with null check
  void _savePhoneChanges() {
    if (_phoneController == null) {
      print('Phone controller is null');
      return;
    }

    setState(() {
      // Update phone in data map
      if (_data.containsKey('phone')) {
        _data['phone'] = _phoneController.text;
      }
      if (_data.containsKey('mobileNumber')) {
        _data['mobileNumber'] = _phoneController.text;
      }

      _isEditingPhone = false;
    });

    // Show success message
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Phone number updated successfully'),
        backgroundColor: primaryColor,
        duration: Duration(seconds: 2),
      ),
    );
  }



  Widget _buildEditablePhoneField() {
    // Ensure controller exists
    if (_phoneController == null) {
      _phoneController = TextEditingController(text: _getUserPhone());
    }

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 12),
      decoration: BoxDecoration(
        color: primaryMedium,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: primaryColor, width: 1.5),
      ),
      child: Row(
        children: [
          Expanded(
            flex: 3,
            child: Text(
              'Mobile Number',
              style: TextStyle(
                fontSize: 13,
                color: lightText,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
          Expanded(
            flex: 4,
            child: TextField(
              controller: _phoneController,
              decoration: InputDecoration(
                hintText: 'Enter phone number',
                hintStyle: TextStyle(fontSize: 13, color: lightText),
                border: InputBorder.none,
                contentPadding: const EdgeInsets.symmetric(vertical: 8),
                isDense: true,
              ),
              style: TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w600,
                color: darkText,
