// New method for editable pricing card
  Widget _buildEditablePricingCard() {
    bool isEditingTariff = _editPriceModes['tariffRange'] ?? false;
    bool isEditingRoomPrice = _editPriceModes['roomPrice'] ?? false;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: borderColor),
        boxShadow: [
          BoxShadow(
            color: shadowColor,
            blurRadius: 20,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Header with Edit/Finish button for Tariff Range
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: primarySoft,
                      borderRadius: BorderRadius.circular(14),
                    ),
                    child: Icon(Icons.attach_money, size: 18, color: primaryColor),
                  ),
                  const SizedBox(width: 12),
                  Text(
                    'Pricing Information',
                    style: TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.w700,
                      color: darkText,
                      letterSpacing: -0.3,
                    ),
                  ),
                ],
              ),
              GestureDetector(
                onTap: () {
                  setState(() {
                    if (isEditingTariff) {
                      // Save tariff changes
                      _autoSaveTariff();
                      _editPriceModes['tariffRange'] = false;
                    } else {
                      // Enter edit mode for tariff
                      _editPriceModes['tariffRange'] = true;
                    }
                  });
                },
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  decoration: BoxDecoration(
                    color: isEditingTariff ? primaryColor : primarySoft,
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color: isEditingTariff ? Colors.transparent : primaryColor.withOpacity(0.2),
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(
                        isEditingTariff ? Icons.check : Icons.edit,
                        size: 14,
                        color: isEditingTariff ? Colors.white : primaryColor,
                      ),
                      const SizedBox(width: 4),
                      Text(
                        isEditingTariff ? 'Save Tariff' : 'Edit Tariff',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: isEditingTariff ? Colors.white : primaryColor,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),

          // Min Tariff Field
          if (_hasValue(_data['minTariff']) || isEditingTariff)
            isEditingTariff
                ? _buildEditablePriceField(
              label: 'Min Tariff (₹)',
              controller: _minTariffController,
              hint: 'Enter minimum price',
            )
                : _buildPriceRow('Min Tariff', _data['minTariff']),

          const SizedBox(height: 12),

          // Max Tariff Field
          if (_hasValue(_data['maxTariff']) || isEditingTariff)
            isEditingTariff
                ? _buildEditablePriceField(
              label: 'Max Tariff (₹)',
              controller: _maxTariffController,
              hint: 'Enter maximum price',
            )
                : _buildPriceRow('Max Tariff', _data['maxTariff']),

          // Extra Bed Available (non-editable)
          if (_data['extraBedAvailable'] != null)
            Padding(
              padding: const EdgeInsets.only(top: 12),
              child: _buildStatusRow(
                'Extra Bed Available',
                _data['extraBedAvailable'] == true,
              ),
            ),

          const Divider(height: 24, color: Colors.grey),

          // Room Price Section Header
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: primarySoft,
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Icon(Icons.hotel, size: 16, color: primaryColor),
                  ),
                  const SizedBox(width: 8),
                  Text(
                    'Room Price per Night',
                    style: TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.w600,
                      color: darkText,
                    ),
                  ),
                ],
              ),
              GestureDetector(
                onTap: () {
                  setState(() {
                    if (isEditingRoomPrice) {
                      // Save room price changes
                      _autoSaveRoomPrice();
                      _editPriceModes['roomPrice'] = false;
                    } else {
                      // Enter edit mode for room price
                      _editPriceModes['roomPrice'] = true;
                    }
                  });
                },
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  decoration: BoxDecoration(
                    color: isEditingRoomPrice ? primaryColor : primarySoft,
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color: isEditingRoomPrice ? Colors.transparent : primaryColor.withOpacity(0.2),
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(
                        isEditingRoomPrice ? Icons.check : Icons.edit,
                        size: 14,
                        color: isEditingRoomPrice ? Colors.white : primaryColor,
                      ),
                      const SizedBox(width: 4),
                      Text(
                        isEditingRoomPrice ? 'Save Price' : 'Edit Price',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: isEditingRoomPrice ? Colors.white : primaryColor,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),

          // Room Price Field
          if (isEditingRoomPrice)
            _buildEditablePriceField(
              label: 'Price per Night',
              controller: _priceController,
              hint: 'Enter price per night',
            )
          else if (_priceController.text.isNotEmpty)
            _buildPriceRow('Price per Night', _priceController.text),
        ],
      ),
    );
  }

// Helper method for editable price field
  Widget _buildEditablePriceField({
    required String label,
    required TextEditingController controller,
    required String hint,
  }) {
    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
      decoration: BoxDecoration(
        color: primaryMedium,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: primaryColor, width: 1.5),
      ),
      child: Row(
        children: [
          Expanded(
            flex: 2,
            child: Text(
              label,
              style: TextStyle(
                fontSize: 13,
                color: darkText,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
          Expanded(
            flex: 3,
            child: TextField(
              controller: controller,
              decoration: InputDecoration(
                hintText: hint,
                hintStyle: TextStyle(fontSize: 13, color: lightText),
                border: InputBorder.none,
                contentPadding: const EdgeInsets.symmetric(vertical: 8),
                isDense: true,
                prefixText: '₹ ',
                prefixStyle: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w500,
                  color: primaryColor,
                ),
              ),
              style: TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w600,
                color: darkText,
              ),
              textAlign: TextAlign.right,
              keyboardType: TextInputType.number,
            ),
          ),
        ],
      ),
    );
  }


  // Auto-save tariff changes
  void _autoSaveTariff() {
    // Save min tariff
    if (_minTariffController.text.isNotEmpty) {
      _data['minTariff'] = _minTariffController.text;
    }

    // Save max tariff
    if (_maxTariffController.text.isNotEmpty) {
      _data['maxTariff'] = _maxTariffController.text;
    }

    // Show success message
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Tariff range updated successfully'),
        backgroundColor: primaryColor,
        duration: Duration(seconds: 2),
      ),
    );
  }

// Auto-save room price changes
  void _autoSaveRoomPrice() {
    if (_priceController.text.isEmpty) return;

    // Update room price in room details
    if (_data['roomDetails'] != null && _data['roomDetails'] is Map) {
      final roomDetails = _data['roomDetails'];
      final selectedRoomTypes = _data['selectedRoomTypes'];

      if (selectedRoomTypes is Map && roomDetails is Map) {
        // Update price for all selected room types
        for (var entry in selectedRoomTypes.entries) {
          if (entry.value == true && roomDetails.containsKey(entry.key)) {
            final details = roomDetails[entry.key];
            if (details is Map) {
              details['price'] = _priceController.text;
            }
          }
        }
      }
