  // Editable Time Row with Dropdown
  Widget _buildEditableTimeRow({
    required String label,
    required TextEditingController controller,
    required ValueChanged<String> onChanged,
  }) {
    String currentValue = controller.text;
    String displayText = '';

    // Find display text for current value
    for (var option in _timeOptions24Hour) {
      if (option['value'] == currentValue) {
        displayText = option['display']!;
        break;
      }
    }

    // If no match found, format the time
    if (displayText.isEmpty && currentValue.isNotEmpty) {
      displayText = _formatTimeForDisplay(currentValue);
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          label,
          style: TextStyle(
            fontSize: 13,
            fontWeight: FontWeight.w500,
            color: darkText,
          ),
        ),
        const SizedBox(height: 8),
        Container(
          height: 50,
          decoration: BoxDecoration(
            border: Border.all(color: borderColor),
            borderRadius: BorderRadius.circular(12),
          ),
          child: DropdownButtonHideUnderline(
            child: DropdownButton<String>(
              value: currentValue.isNotEmpty ? currentValue : null,
              isExpanded: true,
              icon: Icon(Icons.access_time, color: primaryColor, size: 20),
              hint: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 12),
                child: Text(
                  displayText.isNotEmpty ? displayText : 'Select time',
                  style: TextStyle(
                    fontSize: 14,
                    color: displayText.isNotEmpty ? darkText : lightText,
                  ),
                ),
              ),
              items: _timeOptions24Hour.map((option) {
                return DropdownMenuItem<String>(
                  value: option['value'],
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 12),
                    child: Row(
                      children: [
                        Icon(Icons.access_time, size: 16, color: primaryColor),
                        const SizedBox(width: 8),
                        Text(
                          option['display']!,
                          style: TextStyle(
                            fontSize: 14,
                            color: darkText,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }).toList(),
              onChanged: (value) {
                if (value != null) {
                  controller.text = value;
                  onChanged(value);
                }
              },
            ),
          ),
        ),
      ],
    );
  }

