class ThreeStarHotelDetailsScreen extends StatefulWidget {
  final Map<String, dynamic> registrationData;

  const ThreeStarHotelDetailsScreen({
    super.key,
    required this.registrationData,
  });

  @override
  State<ThreeStarHotelDetailsScreen> createState() =>
      _ThreeStarHotelDetailsScreenState();
}


class _ThreeStarHotelDetailsScreenState
    extends State<ThreeStarHotelDetailsScreen>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  late Map<String, dynamic> _data;

  // Editable state for amenities - ALWAYS EDITABLE
  late Map<String, bool> _roomAmenities;
  late Map<String, bool> _hotelFacilities;
  late Map<String, bool> _foodServices;
  late Map<String, bool> _businessServices;
  Map<String, bool> _editModes = {};
  // Editable state for check-in/check-out times
  late String _checkInTime;
  late String _checkOutTime;
  bool _isEditingPhone = false;

  // Add this map to track which room's price is in edit mode
  late Map<String, bool> _priceEditModes;
  late TextEditingController _phoneController;
  // Controllers for time pickers
  final TextEditingController _checkInController = TextEditingController();
  final TextEditingController _checkOutController = TextEditingController();

  // 3-Star specific color scheme (Gold)
  final Color primaryColor = const Color(0xFFDAA520);
  final Color primaryLight = const Color(0xFFDAA520).withOpacity(0.1);
  final Color primarySoft = const Color(0xFFDAA520).withOpacity(0.05);
  final Color primaryMedium = const Color(0xFFDAA520).withOpacity(0.03);

  // Sophisticated neutral palette
  final Color darkText = const Color(0xFF1A1E2B);
  final Color mediumText = const Color(0xFF4A5568);
  final Color lightText = const Color(0xFF8E9AAB);
  final Color bgColor = const Color(0xFFF5F7FA);
  final Color cardColor = Colors.white;
  final Color borderColor = const Color(0xFFE9EDF2);
  final Color shadowColor = const Color(0xFF1A1E2B).withOpacity(0.03);
  final Color starColor = const Color(0xFFFFD700);

  @override
  void initState() {
    super.initState();
    _data = widget.registrationData;
    _tabController = TabController(length: 6, vsync: this);
    _phoneController = TextEditingController(text: _getUserPhone());
    // Initialize editable amenities from registration data
    _initializeAmenities();

    // Initialize check-in/check-out times
    _initializeTimes();

    _priceEditModes = {};
  }

  void _initializeAmenities() {

    _editModes = {
      'room': false,
      'hotel': false,
      'food': false,
      'business': false,
      'custom': false, // If you add custom amenities later
    };
    // Initialize Room Amenities
    if (_data['roomAmenities'] != null && _data['roomAmenities'] is Map) {
      _roomAmenities = Map<String, bool>.from(_data['roomAmenities']);
    } else {
      _roomAmenities = {
        'Air Conditioning': false,
        'Free High-Speed Wi-Fi': false,
        'LED TV (Cable/DTH)': false,
        'Work Desk & Chair': false,
        'Wardrobe / Closet': false,
        'Tea / Coffee Maker': false,
        'Mini Refrigerator': false,
        'Electronic Safe': false,
        'Attached Bathroom with Toiletries': false,
        'Hot & Cold Water': false,
      };
    }

    // Initialize Hotel Facilities
    if (_data['hotelFacilities'] != null && _data['hotelFacilities'] is Map) {
      _hotelFacilities = Map<String, bool>.from(_data['hotelFacilities']);
    } else {
      _hotelFacilities = {
        '24-Hour Front Desk': false,
        'Lift / Elevator': false,
        'Power Backup': false,
        'Daily Housekeeping': false,
        'Luggage Storage': false,
        'CCTV Surveillance': false,
        'Fire Safety System': false,
        'Disabled-Friendly Access': false,
      };
    }

    // Initialize Food Services
    if (_data['foodServices'] != null && _data['foodServices'] is Map) {
      _foodServices = Map<String, bool>.from(_data['foodServices']);
    } else {
      _foodServices = {
        'Multi-Cuisine Restaurant': false,
        'Complimentary Breakfast': false,
        'In-Room Dining': false,
        'Bar / Lounge': false,
        'Banquet / Event Hall': false,
      };
    }

    // Initialize Business Services
    if (_data['businessServices'] != null && _data['businessServices'] is Map) {
      _businessServices = Map<String, bool>.from(_data['businessServices']);
    } else {
      _businessServices = {
        'Conference / Meeting Room': false,
        'Business Center': false,
        'Laundry / Dry Cleaning': false,
        'Travel Desk / Taxi Service': false,
        'Doctor on Call': false,
        'Wake-Up Call': false,
        'Concierge Service': false,
      };
    }
  }

  void _initializeTimes() {
    // Initialize Check-in Time
    _checkInTime = _data['checkInTime']?.toString() ?? '12:00';
    _checkInController.text = _checkInTime;

    // Initialize Check-out Time
    _checkOutTime = _data['checkOutTime']?.toString() ?? '11:00';
    _checkOutController.text = _checkOutTime;
  }

  // Auto-save whenever amenities change
  void _autoSaveAmenities() {
    _data['roomAmenities'] = Map<String, bool>.from(_roomAmenities);
    _data['hotelFacilities'] = Map<String, bool>.from(_hotelFacilities);
    _data['foodServices'] = Map<String, bool>.from(_foodServices);
    _data['businessServices'] = Map<String, bool>.from(_businessServices);
  }

  // Auto-save whenever times change
  void _autoSaveTimes() {
    _data['checkInTime'] = _checkInTime;
    _data['checkOutTime'] = _checkOutTime;
  }


  void _savePhoneChanges() {
    setState(() {
      // Update phone in data map
      if (_data.containsKey('phone')) {
        _data['phone'] = _phoneController.text;
      }
      if (_data.containsKey('mobileNumber')) {
        _data['mobileNumber'] = _phoneController.text;
      }

      _isEditingPhone = false;
    });

    // Show success message
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Phone number updated successfully'),
        backgroundColor: primaryColor,
        duration: Duration(seconds: 2),
      ),
    );
  }

  // Add photo upload methods
  Future<void> _pickAndUploadPhoto() async {
    try {
      final ImagePicker picker = ImagePicker();

      // Show dialog to choose between camera and gallery
      showModalBottomSheet(
        context: context,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
        ),
        builder: (BuildContext context) {
          return SafeArea(
            child: Wrap(
              children: [
                Padding(
                  padding: const EdgeInsets.all(16),
                  child: Text(
                    'Choose Photo',
                    style: TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.w600,
                      color: darkText,
                    ),
                  ),
                ),
                ListTile(
                  leading: Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: primarySoft,
                      shape: BoxShape.circle,
                    ),
                    child: Icon(Icons.photo_library, color: primaryColor),
                  ),
                  title: const Text('Gallery'),
                  onTap: () async {
                    Navigator.pop(context);
                    await _pickImageFromSource(ImageSource.gallery);
                  },
                ),
                ListTile(
                  leading: Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: primarySoft,
                      shape: BoxShape.circle,
                    ),
                    child: Icon(Icons.camera_alt, color: primaryColor),
                  ),
                  title: const Text('Camera'),
                  onTap: () async {
                    Navigator.pop(context);
                    await _pickImageFromSource(ImageSource.camera);
                  },
                ),
                const SizedBox(height: 10),
              ],
            ),
          );
        },
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error picking image: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  Future<void> _pickImageFromSource(ImageSource source) async {
    try {
      final ImagePicker picker = ImagePicker();
      final XFile? image = await picker.pickImage(
        source: source,
        maxWidth: 1000,
        maxHeight: 1000,
        imageQuality: 85,
      );

      if (image != null) {
        setState(() {
          _data['personPhotoInfo'] = {
            'uploaded': true,
            'name': image.name,
            'path': image.path,
          };
          // Also update profilePhoto if that key is used
          _data['profilePhoto'] = {
            'uploaded': true,
            'name': image.name,
            'path': image.path,
          };
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Photo uploaded successfully'),
            backgroundColor: primaryColor,
            duration: Duration(seconds: 2),
          ),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error uploading photo: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  @override
  void dispose() {
    _tabController.dispose();
    _checkInController.dispose();
    _checkOutController.dispose();
    _phoneController.dispose();
    super.dispose();
  }

  // Helper methods for formatting
  String _formatInteger(dynamic value) {
    if (value == null) return '';
    if (value is int) return value.toString();
    if (value is double) return value.toInt().toString();
    if (value is String) {
      double? parsedDouble = double.tryParse(value);
      if (parsedDouble != null) return parsedDouble.toInt().toString();
      return value;
    }
    return value.toString();
  }

  String _formatPrice(dynamic value) {
    if (value == null) return '';
    if (value is double) {
      return value.toStringAsFixed(value.truncateToDouble() == value ? 0 : 2);
    }
    if (value is int) return value.toString();
    if (value is String) {
      double? parsed = double.tryParse(value);
      if (parsed != null) {
        return parsed.toStringAsFixed(
          parsed.truncateToDouble() == parsed ? 0 : 2,
        );
      }
      return value;
    }
    return value.toString();
  }

  String _formatTime(String time) {
    if (time.isEmpty) return 'Not set';
    try {
      if (time.contains(':')) {
        List<String> parts = time.split(':');
        if (parts.length >= 2) {
          int hour = int.parse(parts[0]);
          int minute = int.parse(parts[1].substring(0, 2));
          String period = hour >= 12 ? 'PM' : 'AM';
          int hour12 = hour % 12;
          if (hour12 == 0) hour12 = 12;
          return '${hour12.toString().padLeft(2, '0')}:${minute.toString().padLeft(2, '0')} $period';
        }
      }
    } catch (e) {}
    return time;
  }

  bool _hasValue(dynamic value) {
    if (value == null) return false;
    if (value is String && value.isEmpty) return false;
    if (value is num) return true; // Keep 0 values
    if (value is bool) return true; // Keep false values
    if (value is List) return value.isNotEmpty;
    if (value is Map) {
      // Check if it's a file upload with actual content
      if (value.containsKey('uploaded')) {
        return value['uploaded'] == true;
      }
      return value.isNotEmpty;
    }
    return true;
  }

  String _getRegistrationId() {
    final hotelName = _data['hotelName']?.toString() ?? 'HOTEL';
    final timestamp = DateTime.now().millisecondsSinceEpoch
        .toString()
        .substring(8);
    final namePrefix = hotelName.length >= 3
        ? hotelName.substring(0, 3).toUpperCase()
        : hotelName.toUpperCase();
    return '3STAR-$namePrefix-$timestamp';
  }

  String _getUserFullName() {
    if (_data.containsKey('fullName') &&
        _data['fullName'].toString().isNotEmpty) {
      return _data['fullName'].toString();
    }
    if (_data.containsKey('ownerName') &&
        _data['ownerName'].toString().isNotEmpty) {
      return _data['ownerName'].toString();
    }
    if (_data.containsKey('signatoryName') &&
        _data['signatoryName'].toString().isNotEmpty) {
      return _data['signatoryName'].toString();
    }
    return 'User';
  }

  String _getUserEmail() {
    return _data['email']?.toString() ?? 'Not provided';
  }

  String _getUserPhone() {
    if (_data.containsKey('phone')) {
      return _data['phone'].toString();
    }
    if (_data.containsKey('mobileNumber')) {
      return _data['mobileNumber'].toString();
    }
    return 'Not provided';
  }

  String _getHotelName() {
    return _data['hotelName']?.toString() ?? 'Hotel';
  }

  String _getHotelType() {
    return _data['hotelType']?.toString() ?? '3-Star Hotel';
  }

