  // Step 1: Basic Information
  Widget _buildStep1() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          _buildGlassCard(
            title: 'Hotel Information',
            icon: Icons.business_center,
            children: [
              _buildInfoRow('Hotel Name', _data['hotelName']),
              _buildInfoRow('Hotel Category', '3-Star Hotel'),
              _buildInfoRow('Hotel Type', _data['hotelType']),
              _buildInfoRow(
                'Year of Establishment',
                _data['yearOfEstablishment'],
              ),
              _buildInfoRow('Total Rooms', _data['totalRooms']),
              if (_hasValue(_data['registrationNumber']))
                _buildInfoRow(
                  'Registration Number',
                  _data['registrationNumber'],
                ),
              if (_hasValue(_data['designation']))
                _buildInfoRow('Designation', _data['designation']),
            ],
          ),
          const SizedBox(height: 16),

          // Contact Information Card with Phone Edit functionality
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(20),
            decoration: BoxDecoration(
              color: cardColor,
              borderRadius: BorderRadius.circular(24),
              border: Border.all(color: borderColor),
              boxShadow: [
                BoxShadow(
                  color: shadowColor,
                  blurRadius: 20,
                  offset: const Offset(0, 8),
                ),
                BoxShadow(
                  color: primaryColor.withOpacity(0.02),
                  blurRadius: 10,
                  offset: const Offset(0, 2),
                ),
              ],
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // Header with Title and Edit Button for Phone
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Row(
                      children: [
                        Container(
                          padding: const EdgeInsets.all(10),
                          decoration: BoxDecoration(
                            color: primarySoft,
                            borderRadius: BorderRadius.circular(14),
                          ),
                          child: Icon(Icons.contact_phone, size: 18, color: primaryColor),
                        ),
                        const SizedBox(width: 12),
                        Text(
                          'Contact Information',
                          style: TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w700,
                            color: darkText,
                            letterSpacing: -0.3,
                          ),
                        ),
                      ],
                    ),
                    // Edit button for phone only
                    if (!_isEditingPhone)
                      GestureDetector(
                        onTap: () {
                          setState(() {
                            _isEditingPhone = true;
                            _phoneController.text = _getUserPhone();
                          });
                        },
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 12,
                            vertical: 6,
                          ),
                          decoration: BoxDecoration(
                            color: primarySoft,
                            borderRadius: BorderRadius.circular(20),
                            border: Border.all(color: primaryColor.withOpacity(0.2)),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Icon(
                                Icons.edit,
                                size: 14,
                                color: primaryColor,
                              ),
                              const SizedBox(width: 4),
                              Text(
                                'Edit Phone',
                                style: TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600,
                                  color: primaryColor,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                  ],
                ),
                const SizedBox(height: 16),

                // Contact Info Fields
                _buildInfoRow('Owner/Manager', _data['ownerName']),

                // Phone Number - Editable when in edit mode
                if (_isEditingPhone)
                  _buildEditablePhoneField()
                else
                  _buildInfoRow('Mobile Number', _data['mobileNumber']),

                // Save/Cancel buttons when editing phone
                if (_isEditingPhone)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 12, top: 8),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.end,
                      children: [
                        TextButton(
                          onPressed: () {
                            setState(() {
                              _isEditingPhone = false;
                              _phoneController.text = _getUserPhone();
                            });
                          },
                          style: TextButton.styleFrom(
                            foregroundColor: lightText,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 16,
                              vertical: 8,
                            ),
                          ),
                          child: const Text('Cancel'),
                        ),
                        const SizedBox(width: 8),
                        ElevatedButton(
                          onPressed: _savePhoneChanges,
                          style: ElevatedButton.styleFrom(
                            backgroundColor: primaryColor,
                            foregroundColor: Colors.white,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 16,
                              vertical: 8,
                            ),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(20),
                            ),
                          ),
                          child: const Text('Save'),
                        ),
                      ],
                    ),
                  ),

                // Other non-editable fields
                if (_hasValue(_data['alternateContact']))
                  _buildInfoRow('Alternate Contact', _data['alternateContact']),
                if (_hasValue(_data['email']))
                  _buildInfoRow('Email', _data['email']),
                if (_hasValue(_data['website']))
                  _buildInfoRow('Website', _data['website']),
              ],
            ),
          ),

          // Profile Photo Tile (shows after upload)
          if (_data.containsKey('profilePhoto') &&
              _data['profilePhoto'] != null &&
              _data['profilePhoto']['uploaded'] == true)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildProfilePhotoTile(_data['profilePhoto']),
            ),
        ],
      ),
    );
  }

// Add this helper method for editable phone field
  Widget _buildEditablePhoneField() {
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 12),
      decoration: BoxDecoration(
        color: primaryMedium,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: primaryColor, width: 1.5),
      ),
      child: Row(
        children: [
          Expanded(
            flex: 3,
            child: Text(
              'Mobile Number',
              style: TextStyle(
                fontSize: 13,
                color: lightText,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
          Expanded(
            flex: 4,
            child: TextField(
              controller: _phoneController,
              decoration: InputDecoration(
                hintText: 'Enter phone number',
                hintStyle: TextStyle(fontSize: 13, color: lightText),
                border: InputBorder.none,
                contentPadding: const EdgeInsets.symmetric(vertical: 8),
                isDense: true,
              ),
              style: TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w600,
                color: darkText,
              ),
              textAlign: TextAlign.right,
              keyboardType: TextInputType.phone,
            ),
          ),
        ],
      ),
    );
  }

  // Step 2: Address Details
  Widget _buildStep2() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          _buildGlassCard(
            title: 'Address Details',
            icon: Icons.location_on,
            children: [
              _buildInfoRow('Address Line 1', _data['addressLine1']),
              if (_hasValue(_data['addressLine2']))
                _buildInfoRow('Address Line 2', _data['addressLine2']),
              _buildInfoRow('City', _data['city']),
              _buildInfoRow('District', _data['district']),
              _buildInfoRow('State', _data['state']),
              _buildInfoRow('PIN Code', _data['pinCode']),
              if (_hasValue(_data['country']))
                _buildInfoRow('Country', _data['country']),
            ],
          ),

          // Additional Addresses
          if (_data.containsKey('additionalAddresses') &&
              _data['additionalAddresses'] != null &&
              (_data['additionalAddresses'] as List).isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildAdditionalAddressesCard(),
            ),
        ],
      ),
    );
  }

  Widget _buildAdditionalAddressesCard() {
    final addresses = _data['additionalAddresses'] as List;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: borderColor),
        boxShadow: [
          BoxShadow(
            color: shadowColor,
            blurRadius: 20,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: primarySoft,
                  borderRadius: BorderRadius.circular(14),
                ),
                child: Icon(
                  Icons.location_on_outlined,
                  size: 18,
                  color: primaryColor,
                ),
              ),
              const SizedBox(width: 12),
              Text(
                'Additional Addresses',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  color: darkText,
                  letterSpacing: -0.3,
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          ...addresses.asMap().entries.map((entry) {
