  // Room Details with Editable Price
  List<Widget> _buildRoomDetails() {
    List<Widget> widgets = [];
    final roomDetails = _data['roomDetails'];
    final selectedRoomTypes = _data['selectedRoomTypes'];

    if (roomDetails is Map && selectedRoomTypes is Map) {
      selectedRoomTypes.forEach((type, isSelected) {
        if (isSelected == true && roomDetails.containsKey(type)) {
          final details = roomDetails[type];
          if (details is Map) {
            bool hasData =
                _hasValue(details['rooms']) ||
                    _hasValue(details['occupancy']) ||
                    _hasValue(details['price']);

            if (hasData) {
              // Initialize edit mode for this room type if not exists
              if (!_editPriceModes.containsKey(type)) {
                _editPriceModes[type] = false;
              }

              bool isEditingPrice = _editPriceModes[type] ?? false;
              TextEditingController priceController = TextEditingController(
                  text: details['price']?.toString() ?? ''
              );

              widgets.add(
                Container(
                  margin: const EdgeInsets.only(bottom: 12),
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: cardColor,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: borderColor),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // Header with room type and edit button
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Row(
                            children: [
                              Container(
                                padding: const EdgeInsets.all(8),
                                decoration: BoxDecoration(
                                  color: primarySoft,
                                  borderRadius: BorderRadius.circular(10),
                                ),
                                child: Icon(
                                  Icons.hotel,
                                  size: 16,
                                  color: primaryColor,
                                ),
                              ),
                              const SizedBox(width: 12),
                              Text(
                                type.toString(),
                                style: TextStyle(
                                  fontSize: 14,
                                  fontWeight: FontWeight.w700,
                                  color: darkText,
                                ),
                              ),
                            ],
                          ),
                          // Edit/Finish button for price only
                          if (_hasValue(details['price']))
                            GestureDetector(
                              onTap: () {
                                setState(() {
                                  if (isEditingPrice) {
                                    // Save price
                                    double? newPrice = double.tryParse(priceController.text);
                                    if (newPrice != null) {
                                      _autoSavePrice(type, newPrice);
                                      ScaffoldMessenger.of(context).showSnackBar(
                                        SnackBar(
                                          content: Text('Price updated for ${type.toString()}'),
                                          backgroundColor: primaryColor,
                                          duration: Duration(seconds: 2),
                                        ),
                                      );
                                    }
                                    _editPriceModes[type] = false;
                                  } else {
                                    // Enter edit mode
                                    priceController.text = details['price']?.toString() ?? '';
                                    _editPriceModes[type] = true;
                                  }
                                });
                              },
                              child: Container(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 10,
                                  vertical: 5,
                                ),
                                decoration: BoxDecoration(
                                  color: isEditingPrice ? primaryColor : primarySoft,
                                  borderRadius: BorderRadius.circular(20),
                                  border: Border.all(
                                    color: isEditingPrice ? Colors.transparent : primaryColor.withOpacity(0.2),
                                  ),
                                ),
                                child: Row(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    Icon(
                                      isEditingPrice ? Icons.check : Icons.edit,
                                      size: 12,
                                      color: isEditingPrice ? Colors.white : primaryColor,
                                    ),
                                    const SizedBox(width: 4),
                                    Text(
                                      isEditingPrice ? 'Save' : 'Edit Price',
                                      style: TextStyle(
                                        fontSize: 10,
                                        fontWeight: FontWeight.w600,
                                        color: isEditingPrice ? Colors.white : primaryColor,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ),
                        ],
                      ),
                      const SizedBox(height: 12),

                      // Non-editable fields
                      if (_hasValue(details['rooms']))
                        _buildDetailRow('Number of Rooms', details['rooms']),

                      if (_hasValue(details['occupancy']))
                        _buildDetailRow('Max Occupancy', details['occupancy']),

                      if (details['ac'] != null)
                        _buildDetailRow(
                          'AC',
                          details['ac'] == true ? 'Yes' : 'No',
                        ),

                      if (_hasValue(details['bedType']))
                        _buildDetailRow('Bed Type', details['bedType']),

                      // Price per Night - Editable
                      if (_hasValue(details['price']))
                        isEditingPrice
                            ? _buildEditablePriceField(
                          label: 'Price per Night',
                          controller: priceController,
                        )
                            : _buildDetailRow(
                          'Price per Night',
                          details['price'],
                          isPrice: true,
                        ),
                    ],
                  ),
                ),
              );
            }
          }
        }
      });
    }
    return widgets;
  }

  // Editable Price Field
  Widget _buildEditablePriceField({
    required String label,
    required TextEditingController controller,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(label, style: TextStyle(fontSize: 12, color: lightText)),
          Container(
            width: 120,
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
            decoration: BoxDecoration(
              color: primaryMedium,
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: primaryColor),
            ),
            child: Row(
              children: [
                Text(
                  '₹',
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w600,
                    color: primaryColor,
                  ),
                ),
                Expanded(
                  child: TextField(
                    controller: controller,
                    decoration: InputDecoration(
                      hintText: 'Enter price',
                      hintStyle: TextStyle(fontSize: 12, color: lightText),
                      border: InputBorder.none,
                      contentPadding: const EdgeInsets.symmetric(horizontal: 4),
                      isDense: true,
                    ),
                    style: TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w600,
                      color: darkText,
                    ),
                    textAlign: TextAlign.right,
                    keyboardType: TextInputType.number,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // Detail Row
  Widget _buildDetailRow(String label, dynamic value, {bool isPrice = false}) {
    if (!_hasValue(value)) return const SizedBox.shrink();

    String displayValue;
    if (isPrice) {
      displayValue = '₹${_formatPrice(value)}';
    } else if (label.contains('Rooms') || label.contains('Occupancy')) {
      displayValue = _formatInteger(value);
    } else {
      displayValue = value.toString();
    }

    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(label, style: TextStyle(fontSize: 12, color: lightText)),
          Text(
            displayValue,
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w600,
              color: darkText,
            ),
          ),
        ],
      ),
    );
  }

  // Amenity Card
  Widget _buildAmenityCard(String title, dynamic amenities) {
    if (amenities is! Map) return const SizedBox.shrink();

    final selected = amenities.entries
        .where((e) => e.value == true)
        .map((e) => e.key)
        .toList();

    if (selected.isEmpty) return const SizedBox.shrink();

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: borderColor),
        boxShadow: [
          BoxShadow(
            color: shadowColor,
            blurRadius: 20,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: primarySoft,
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Icon(Icons.star, size: 16, color: primaryColor),
              ),
              const SizedBox(width: 12),
              Text(
                title,
                style: TextStyle(
                  fontSize: 15,
                  fontWeight: FontWeight.w700,
                  color: darkText,
                  letterSpacing: -0.3,
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: selected
                .map(
                  (item) => Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 6,
                ),
                decoration: BoxDecoration(
                  color: primarySoft,
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: primaryColor.withOpacity(0.15)),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.check, size: 12, color: primaryColor),
                    const SizedBox(width: 4),
                    Text(
                      item.toString(),
                      style: TextStyle(
                        fontSize: 11,
                        color: primaryColor,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                  ],
                ),
              ),
            )
                .toList(),
          ),
        ],
      ),
    );
  }

  // Uploaded Documents
  List<Widget> _buildUploadedDocuments() {
    List<Widget> widgets = [];
    final uploadedFiles = _data['uploadedFiles'];

    if (uploadedFiles is Map) {
      uploadedFiles.forEach((key, value) {
        // Skip digital signature as it's handled separately
        // if (key == 'Digital Signature') return;

        if (value is Map && value['uploaded'] == true) {
          widgets.add(
            Container(
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: primarySoft,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: primaryColor.withOpacity(0.15)),
              ),
              child: Row(
                children: [
                  Icon(Icons.check_circle, size: 16, color: primaryColor),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          key,
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w600,
                            color: darkText,
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          value['name'] ?? 'Uploaded successfully',
                          style: TextStyle(fontSize: 11, color: lightText),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          );
        }
      });
    }

    return widgets;
  }

  // Photo Tile
  Widget _buildPhotoTile(Map<String, dynamic> photoInfo) {
