    super.initState();
    _data = widget.registrationData;
    _tabController = TabController(length: 6, vsync: this);

    _phoneController = TextEditingController(text: _getUserPhone());
    // Initialize time controllers
    _checkInController = TextEditingController(
        text: _data['checkInTime']?.toString() ?? ''
    );
    _checkOutController = TextEditingController(
        text: _data['checkOutTime']?.toString() ?? ''
    );

    _initializeAmenities();
    _initializePriceControllers();
  }
  void _initializePriceControllers() {
    _minPriceControllers = {};
    _maxPriceControllers = {};
    _priceEditModes = {};

    final roomDetails = _data['roomDetails'];
    final selectedRoomTypes = _data['selectedRoomTypes'];

    if (roomDetails is Map && selectedRoomTypes is Map) {
      selectedRoomTypes.forEach((type, isSelected) {
        if (isSelected == true && roomDetails.containsKey(type)) {
          final details = roomDetails[type];
          if (details is Map) {
            _priceEditModes[type] = false;

            // Initialize min price controller
            String minPriceValue = '';
            if (details['minPrice'] != null) {
              if (details['minPrice'] is double || details['minPrice'] is int) {
                minPriceValue = details['minPrice'].toString();
              } else {
                minPriceValue = details['minPrice'].toString();
              }
            }
            _minPriceControllers[type] = TextEditingController(text: minPriceValue);

            // Initialize max price controller
            String maxPriceValue = '';
            if (details['maxPrice'] != null) {
              if (details['maxPrice'] is double || details['maxPrice'] is int) {
                maxPriceValue = details['maxPrice'].toString();
              } else {
                maxPriceValue = details['maxPrice'].toString();
              }
            }
            _maxPriceControllers[type] = TextEditingController(text: maxPriceValue);
          }
        }
      });
    }
  }
  @override
  void dispose() {
    _tabController.dispose();
    _phoneController.dispose();
    _checkInController.dispose();
    _checkOutController.dispose();

    _minPriceControllers.forEach((key, controller) => controller.dispose());
    _maxPriceControllers.forEach((key, controller) => controller.dispose());
    super.dispose();
  }

