  void _savePriceChanges(String roomType) {
    setState(() {
      final minPrice = double.tryParse(_minPriceControllers[roomType]?.text ?? '0') ?? 0;
      final maxPrice = double.tryParse(_maxPriceControllers[roomType]?.text ?? '0') ?? 0;

      // Update the data
      if (_data['roomDetails'] != null && _data['roomDetails'][roomType] != null) {
        _data['roomDetails'][roomType]['minPrice'] = minPrice;
        _data['roomDetails'][roomType]['maxPrice'] = maxPrice;
      }

      _priceEditModes[roomType] = false;
    });

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Price updated for $roomType'),
        backgroundColor: primaryColor,
        duration: Duration(seconds: 2),
      ),
    );
