  // Step 4: Amenities - EDITABLE with edit mode per section

  Widget _buildStep4() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          // Room Amenities - With edit mode
          if (_roomAmenities.isNotEmpty)
            _buildEditableSection(
              title: 'In-Room Luxury Amenities',
              icon: Icons.bed,
              amenities: _roomAmenities,
              sectionId: 'room',
            ),

          // Hotel Facilities - With edit mode
          if (_hotelFacilities.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildEditableSection(
                title: 'Hotel Infrastructure & Services',
                icon: Icons.business_center,
                amenities: _hotelFacilities,
                sectionId: 'hotel',
              ),
            ),

          // Dining Services - With edit mode
          if (_diningServices.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildEditableSection(
                title: 'Dining, Events & Entertainment',
                icon: Icons.restaurant,
                amenities: _diningServices,
                sectionId: 'dining',
              ),
            ),

          // Wellness & Recreation - With edit mode
          if (_wellnessRecreation.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildEditableSection(
                title: 'Wellness, Leisure & Recreation',
                icon: Icons.spa,
                amenities: _wellnessRecreation,
                sectionId: 'wellness',
