  // Editable Time Field with Clock Design (like registration form)
  Widget _buildEditableTimeField({
    required String label,
    required TextEditingController controller,
    required ValueChanged<String> onChanged,
  }) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          label,
          style: TextStyle(
            fontSize: 13,
            fontWeight: FontWeight.w500,
            color: darkText,
          ),
        ),
        const SizedBox(height: 8),
        GestureDetector(
          onTap: () => _selectTime(context, controller, onChanged),
          child: Container(
            height: 50,
            padding: const EdgeInsets.symmetric(horizontal: 12),
            decoration: BoxDecoration(
              border: Border.all(color: borderColor),
              borderRadius: BorderRadius.circular(12),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  controller.text.isNotEmpty
                      ? _formatTimeForDisplay(controller.text)
                      : 'Select time',
                  style: TextStyle(
                    fontSize: 14,
                    color: controller.text.isNotEmpty ? darkText : lightText,
                  ),
                ),
                Icon(
                  Icons.access_time,
                  size: 20,
                  color: primaryColor,
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }

// Time picker method (same as registration form)
  Future<void> _selectTime(
      BuildContext context,
      TextEditingController controller,
      ValueChanged<String> onChanged,
      ) async {
    // Parse current time or use current local time as default
    TimeOfDay initialTime = TimeOfDay.now();

    if (controller.text.isNotEmpty) {
      try {
        List<String> parts = controller.text.split(':');
        if (parts.length >= 2) {
          int hour = int.parse(parts[0]);
          int minute = int.parse(parts[1].substring(0, 2));
          initialTime = TimeOfDay(hour: hour, minute: minute);
        }
      } catch (e) {
        // Use current time if parsing fails
        initialTime = TimeOfDay.now();
      }
    }

    TimeOfDay? pickedTime = await showTimePicker(
      context: context,
      initialTime: initialTime,
      builder: (BuildContext context, Widget? child) {
        return MediaQuery(
          data: MediaQuery.of(context).copyWith(alwaysUse24HourFormat: false),
          child: child!,
        );
      },
    );

    if (pickedTime != null) {
      // Store in 24-hour format for consistency
      String formattedTime =
          '${pickedTime.hour.toString().padLeft(2, '0')}:${pickedTime.minute.toString().padLeft(2, '0')}';
      controller.text = formattedTime;
      onChanged(formattedTime);
    }
  }

// Helper method to format time for display
  String _formatTimeForDisplay(String time24) {
    if (time24.isEmpty) return '';
    try {
      if (time24.contains(':')) {
        List<String> parts = time24.split(':');
        if (parts.length >= 2) {
          int hour = int.parse(parts[0]);
          int minute = int.parse(parts[1].substring(0, 2));

          String period = hour >= 12 ? 'PM' : 'AM';
          int hour12 = hour % 12;
          if (hour12 == 0) hour12 = 12;

          return '${hour12.toString().padLeft(2, '0')}:${minute.toString().padLeft(2, '0')} $period';
        }
      }
    } catch (e) {
      return time24;
    }
    return time24;
  }

