  // Room Details - EDITABLE PRICES
  List<Widget> _buildRoomDetails() {
    List<Widget> widgets = [];
    final roomDetails = _data['roomDetails'];
    final selectedRoomTypes = _data['selectedRoomTypes'];

    if (roomDetails is Map && selectedRoomTypes is Map) {
      selectedRoomTypes.forEach((type, isSelected) {
        if (isSelected == true && roomDetails.containsKey(type)) {
          final details = roomDetails[type];
          if (details is Map) {
            bool hasData =
                _hasValue(details['rooms']) ||
                    _hasValue(details['occupancy']) ||
                    _hasValue(details['ac']) ||
                    _hasValue(details['bedType']) ||
                    _hasValue(details['minPrice']) ||
                    _hasValue(details['maxPrice']);

            if (hasData) {
              bool isPriceEditMode = _priceEditModes[type] ?? false;

              widgets.add(
                Container(
                  margin: const EdgeInsets.only(bottom: 12),
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: cardColor,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: borderColor),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // Room Type Header with Edit Price button
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Row(
                            children: [
                              Container(
                                padding: const EdgeInsets.all(8),
                                decoration: BoxDecoration(
                                  color: primarySoft,
                                  borderRadius: BorderRadius.circular(10),
                                ),
                                child: Icon(
                                  Icons.hotel,
                                  size: 16,
                                  color: primaryColor,
                                ),
                              ),
                              const SizedBox(width: 12),
                              Text(
                                type.toString(),
                                style: TextStyle(
                                  fontSize: 14,
                                  fontWeight: FontWeight.w700,
                                  color: darkText,
                                ),
                              ),
                            ],
                          ),
                          // Edit Price button
                          GestureDetector(
                            onTap: () {
                              setState(() {
                                if (isPriceEditMode) {
                                  // Save changes
                                  _savePriceChanges(type);
                                } else {
                                  // Enter edit mode
                                  _priceEditModes[type] = true;
                                }
                              });
                            },
                            child: Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 6,
                              ),
                              decoration: BoxDecoration(
                                color: isPriceEditMode ? primaryColor : primarySoft,
                                borderRadius: BorderRadius.circular(20),
                                border: Border.all(
                                  color: isPriceEditMode ? Colors.transparent : primaryColor.withOpacity(0.2),
                                ),
                              ),
                              child: Row(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Icon(
                                    isPriceEditMode ? Icons.check : Icons.edit,
                                    size: 12,
                                    color: isPriceEditMode ? Colors.white : primaryColor,
                                  ),
                                  const SizedBox(width: 4),
                                  Text(
                                    isPriceEditMode ? 'Save Price' : 'Edit Price',
                                    style: TextStyle(
                                      fontSize: 10,
                                      fontWeight: FontWeight.w600,
                                      color: isPriceEditMode ? Colors.white : primaryColor,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),

                      // Non-editable fields
                      if (_hasValue(details['rooms']))
                        _buildDetailRow('Number of Units', _formatInteger(details['rooms'])),

                      if (_hasValue(details['occupancy']))
                        _buildDetailRow('Max Occupancy', '${_formatInteger(details['occupancy'])} Persons'),

                      if (details['ac'] != null)
                        _buildDetailRow(
                          'Climate Control',
                          details['ac'] == true ? 'Yes' : 'No',
                        ),

                      if (_hasValue(details['bedType']))
                        _buildDetailRow('Bed Type', details['bedType']),

                      // Price Range - EDITABLE
                      if (_hasValue(details['minPrice']) || _hasValue(details['maxPrice']))
                        isPriceEditMode
                            ? _buildEditablePriceRow(type)
                            : _buildDetailRow(
                          'Price Range',
                          '₹${_formatPrice(details['minPrice'])} - ₹${_formatPrice(details['maxPrice'])}',
                        ),
                    ],
                  ),
                ),
              );
            }
          }
        }
      });
    }
    return widgets;
  }

