  String _maskAccountNumber(String accountNumber) {
    if (accountNumber.length <= 4) return accountNumber;
    return 'XXXX XXXX ${accountNumber.substring(accountNumber.length - 4)}';
  }
}


class SixStarHotelDetailsScreen extends StatefulWidget {
  final Map<String, dynamic> registrationData;

  const SixStarHotelDetailsScreen({
    Key? key,
    required this.registrationData,
  }) : super(key: key);

  @override
  State<SixStarHotelDetailsScreen> createState() => _SixStarHotelDetailsScreenState();
}

class _SixStarHotelDetailsScreenState extends State<SixStarHotelDetailsScreen>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  late Map<String, dynamic> _data;
// Add these with your other late variables
  late Map<String, bool> _roomAmenities;
  late Map<String, bool> _hotelInfrastructure;
  late Map<String, bool> _diningExperiences;
  late Map<String, bool> _wellnessLeisure;
  late Map<String, bool> _guestPrivileges;
  bool _isEditingPhone = false;
  late TextEditingController _phoneController;
// Track edit modes for each section
  Map<String, bool> _editModes = {};
  // Add this map to track which room's price range is in edit mode
  late Map<String, bool> _priceEditModes;
  // 6-Star specific color scheme (Royal Gold & Purple)
  final Color primaryColor = const Color(0xFFD4AF37); // Royal Gold
  final Color secondaryColor = const Color(0xFF7851A9); // Royal Purple
  final Color primaryLight = const Color(0xFFD4AF37).withOpacity(0.1);
  final Color primarySoft = const Color(0xFFD4AF37).withOpacity(0.05);
  final Color primaryMedium = const Color(0xFFD4AF37).withOpacity(0.03);
  final Color purpleLight = const Color(0xFF7851A9).withOpacity(0.1);

  // Sophisticated neutral palette
  final Color darkText = const Color(0xFF1A1E2B);
  final Color mediumText = const Color(0xFF4A5568);
  final Color lightText = const Color(0xFF8E9AAB);
  final Color bgColor = const Color(0xFFF5F7FA);
  final Color cardColor = Colors.white;
  final Color borderColor = const Color(0xFFE9EDF2);
  final Color shadowColor = const Color(0xFF1A1E2B).withOpacity(0.03);
  final Color starColor = const Color(0xFFFFD700);
  final Color successColor = const Color(0xFF10B981);
// Add these with your other late variables
  late TextEditingController _checkInController;
  late TextEditingController _checkOutController;
  late String _checkInTime;
  late String _checkOutTime;

  @override
  void initState() {
    super.initState();
    _data = widget.registrationData;
    _tabController = TabController(length: 6, vsync: this);
    _initializeAmenities();
    _phoneController = TextEditingController(text: _getUserPhone());
    _checkInTime = _data['checkInTime']?.toString() ?? '';
    _checkOutTime = _data['checkOutTime']?.toString() ?? '';

    _checkInController = TextEditingController(text: _checkInTime);
    _checkOutController = TextEditingController(text: _checkOutTime);
    _priceEditModes = {};

    // DEBUGGING - Add this to see what data you're receiving
    print('=== SixStarHotelDetailsScreen INIT ===');
    print('Data keys: ${_data.keys.toList()}');
    print('roomAmenities exists: ${_data.containsKey('roomAmenities')}');
    print('roomAmenities: ${_data['roomAmenities']}');
    print('hotelInfrastructure exists: ${_data.containsKey('hotelInfrastructure')}');
    print('roomDetails exists: ${_data.containsKey('roomDetails')}');
    print('roomDetails: ${_data['roomDetails']}');
  }
  @override
  void dispose() {
    _tabController.dispose();
    _phoneController.dispose();
    _checkInController.dispose();
    _checkOutController.dispose();
    super.dispose();
  }
  void _autoSavePolicies() {
    _data['checkInTime'] = _checkInTime;
    _data['checkOutTime'] = _checkOutTime;
  }
