  // Compliance Certificates
  Widget _buildComplianceCertificates() {
    final List<String> certificates = [];

    if (_data['fireSafetyNoc'] == true) certificates.add('Fire Safety & Disaster NOC');
    if (_data['environmentalCert'] == true) certificates.add('Environmental & Sustainability');
    if (_data['internationalCert'] == true) certificates.add('International Safety/Quality');

    if (certificates.isEmpty) return const SizedBox.shrink();

    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Compliance Certificates',
            style: TextStyle(
              fontSize: 13,
              color: lightText,
              fontWeight: FontWeight.w500,
            ),
          ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: certificates.map((cert) => Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
              decoration: BoxDecoration(
                color: purpleLight,
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: secondaryColor.withOpacity(0.2)),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(Icons.check_circle, size: 12, color: secondaryColor),
                  const SizedBox(width: 4),
                  Text(
                    cert,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w500,
                      color: secondaryColor,
                    ),
                  ),
                ],
              ),
            )).toList(),
          ),
        ],
      ),
    );
  }

  // Room Types
  List<Widget> _buildRoomTypes() {
    List<Widget> widgets = [];
    final selectedRoomTypes = _data['selectedRoomTypes'];

    if (selectedRoomTypes is Map) {
      final selected = selectedRoomTypes.entries
          .where((e) => e.value == true)
          .map((e) => e.key)
          .toList();

      if (selected.isNotEmpty) {
        widgets.add(
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: Wrap(
              spacing: 8,
              runSpacing: 8,
              children: selected
                  .map(
                    (type) => Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: [primaryColor, secondaryColor],
                    ),
                    borderRadius: BorderRadius.circular(20),
                    boxShadow: [
                      BoxShadow(
                        color: primaryColor.withOpacity(0.2),
                        blurRadius: 8,
                        offset: const Offset(0, 2),
                      ),
                    ],
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      ...List.generate(
                        6,
                            (index) => const Icon(
                          Icons.star,
                          size: 8,
                          color: Colors.white,
                        ),
                      ),
                      const SizedBox(width: 6),
                      Text(
                        type.toString(),
                        style: const TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: Colors.white,
                        ),
                      ),
                    ],
                  ),
                ),
              )
                  .toList(),
            ),
          ),
        );
      }
    }
    return widgets;
  }

