  // Room Details - With editable price fields
  List<Widget> _buildRoomDetails() {
    List<Widget> widgets = [];
    final roomDetails = _data['roomDetails'];
    final selectedRoomTypes = _data['selectedRoomTypes'];

    if (roomDetails is Map && selectedRoomTypes is Map) {
      selectedRoomTypes.forEach((type, isSelected) {
        if (isSelected == true && roomDetails.containsKey(type)) {
          final details = roomDetails[type];
          if (details is Map) {
            bool hasData =
                _hasValue(details['rooms']) ||
                    _hasValue(details['occupancy']) ||
                    _hasValue(details['bedType']) ||
                    _hasValue(details['minPrice']) ||
                    _hasValue(details['maxPrice']);

            if (hasData) {
              widgets.add(
                Container(
                  margin: const EdgeInsets.only(bottom: 12),
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: cardColor,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: borderColor),
                    gradient: LinearGradient(
                      colors: [Colors.white, purpleLight],
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // Room Type Header
                      Row(
                        children: [
                          Container(
                            padding: const EdgeInsets.all(8),
                            decoration: BoxDecoration(
                              color: primarySoft,
                              borderRadius: BorderRadius.circular(10),
                            ),
                            child: Icon(
                              Icons.villa,
                              size: 16,
                              color: primaryColor,
                            ),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Text(
                              type.toString(),
                              style: TextStyle(
                                fontSize: 14,
                                fontWeight: FontWeight.w700,
                                color: primaryColor,
                              ),
                            ),
                          ),
                          if (details['bedType'] != null)
                            Container(
                              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                              decoration: BoxDecoration(
                                color: secondaryColor.withOpacity(0.1),
                                borderRadius: BorderRadius.circular(12),
                                border: Border.all(color: secondaryColor.withOpacity(0.2)),
                              ),
                              child: Text(
                                details['bedType'],
                                style: TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w600,
                                  color: secondaryColor,
                                ),
                              ),
                            ),
                        ],
                      ),
                      const SizedBox(height: 12),

                      // Number of Units
                      if (_hasValue(details['rooms']))
                        _buildDetailRow('Number of Units', _formatInteger(details['rooms'])),

                      // Max Occupancy
                      if (_hasValue(details['occupancy']))
                        _buildDetailRow('Max Occupancy', '${_formatInteger(details['occupancy'])} Persons'),

                      // Editable Price Range Field
                      if (_hasValue(details['minPrice']) || _hasValue(details['maxPrice']))
                        _buildEditablePriceRangeFieldForRoom(
                          roomType: type.toString(),
                          minPrice: details['minPrice'],
                          maxPrice: details['maxPrice'],
                          isEditing: _priceEditModes[type] ?? false,
                          onSave: (minVal, maxVal) {
                            setState(() {
                              // Update the price values
                              details['minPrice'] = minVal;
                              details['maxPrice'] = maxVal;
                              // Save to main data
                              _data['roomDetails'] = roomDetails;
                              // Exit edit mode
                              _priceEditModes[type] = false;
                              // Auto-save
                              _autoSaveRoomDetails();
                            });
                          },
                          onCancel: () {
                            setState(() {
                              _priceEditModes[type] = false;
                            });
                          },
                        ),
                    ],
                  ),
                ),
              );
            }
          }
        }
      });
    }
    return widgets;
  }

// Helper method for editable price range field (specifically for rooms)
  Widget _buildEditablePriceRangeFieldForRoom({
    required String roomType,
    required dynamic minPrice,
    required dynamic maxPrice,
    required bool isEditing,
    required Function(double, double) onSave,
    required VoidCallback onCancel,
  }) {
    final TextEditingController _minController = TextEditingController(
      text: minPrice?.toString() ?? '',
    );
    final TextEditingController _maxController = TextEditingController(
      text: maxPrice?.toString() ?? '',
    );

    if (!isEditing) {
      // View Mode - Show price with edit button
      return Padding(
        padding: const EdgeInsets.only(top: 8),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Expanded(
              child: Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: successColor.withOpacity(0.1),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: successColor.withOpacity(0.2)),
                ),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      'Price Range',
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w500,
                        color: lightText,
                      ),
                    ),
                    Text(
                      '₹${_formatPrice(minPrice)} - ₹${_formatPrice(maxPrice)}',
                      style: TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w700,
                        color: successColor,
                      ),
                    ),
                  ],
                ),
              ),
            ),
            // Edit Button
            GestureDetector(
              onTap: () {
                setState(() {
                  _priceEditModes[roomType] = true;
                });
              },
              child: Container(
                margin: const EdgeInsets.only(left: 8),
                padding: const EdgeInsets.all(6),
                decoration: BoxDecoration(
                  color: primarySoft,
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: primaryColor.withOpacity(0.2)),
                ),
                child: Icon(
                  Icons.edit,
                  size: 16,
                  color: primaryColor,
                ),
              ),
            ),
          ],
        ),
      );
    }

    // Edit Mode - Show editable fields
    return Container(
      margin: const EdgeInsets.only(top: 8),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: primarySoft,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: primaryColor, width: 1.5),
      ),
      child: Column(
        children: [
          // Min Price Field
          Row(
            children: [
              Expanded(
                flex: 3,
                child: Text(
                  'Min Price',
                  style: TextStyle(
                    fontSize: 12,
                    color: mediumText,
                    fontWeight: FontWeight.w500,
                  ),
                ),
              ),
              Expanded(
                flex: 4,
                child: TextField(
                  controller: _minController,
                  decoration: InputDecoration(
                    prefixText: '₹ ',
                    hintText: 'Enter min price',
                    hintStyle: TextStyle(fontSize: 12, color: lightText),
                    border: InputBorder.none,
                    contentPadding: const EdgeInsets.symmetric(vertical: 4),
                    isDense: true,
                  ),
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w600,
                    color: darkText,
                  ),
                  textAlign: TextAlign.right,
                  keyboardType: TextInputType.number,
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),

          // Max Price Field
          Row(
            children: [
              Expanded(
                flex: 3,
                child: Text(
                  'Max Price',
                  style: TextStyle(
                    fontSize: 12,
                    color: mediumText,
                    fontWeight: FontWeight.w500,
                  ),
                ),
              ),
              Expanded(
                flex: 4,
                child: TextField(
                  controller: _maxController,
                  decoration: InputDecoration(
                    prefixText: '₹ ',
                    hintText: 'Enter max price',
                    hintStyle: TextStyle(fontSize: 12, color: lightText),
                    border: InputBorder.none,
                    contentPadding: const EdgeInsets.symmetric(vertical: 4),
                    isDense: true,
                  ),
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w600,
                    color: darkText,
                  ),
                  textAlign: TextAlign.right,
                  keyboardType: TextInputType.number,
                ),
              ),
            ],
          ),

          const SizedBox(height: 12),

          // Validation Message
          ..._buildPriceValidationMessage(_minController.text, _maxController.text),

          // Save/Cancel Buttons
          Row(
            mainAxisAlignment: MainAxisAlignment.end,
            children: [
              TextButton(
                onPressed: onCancel,
                style: TextButton.styleFrom(
                  foregroundColor: lightText,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 4,
                  ),
                  minimumSize: Size.zero,
                ),
                child: const Text('Cancel', style: TextStyle(fontSize: 11)),
              ),
              const SizedBox(width: 8),
              ElevatedButton(
                onPressed: () {
                  double? minVal = double.tryParse(_minController.text);
                  double? maxVal = double.tryParse(_maxController.text);

                  if (minVal != null && maxVal != null) {
                    if (minVal <= maxVal) {
                      onSave(minVal, maxVal);
                    } else {
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(
                          content: Text('Min price must be less than or equal to max price'),
                          backgroundColor: Colors.red,
                          duration: Duration(seconds: 2),
                        ),
                      );
                    }
                  } else {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text('Please enter valid prices'),
                        backgroundColor: Colors.red,
                        duration: Duration(seconds: 2),
                      ),
                    );
                  }
                },
                style: ElevatedButton.styleFrom(
                  backgroundColor: primaryColor,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 4,
                  ),
                  minimumSize: Size.zero,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                ),
                child: const Text('Save', style: TextStyle(fontSize: 11)),
              ),
            ],
          ),
        ],
      ),
    );
  }

// Helper method for price validation
  List<Widget> _buildPriceValidationMessage(String minText, String maxText) {
    if (minText.isNotEmpty && maxText.isNotEmpty) {
      double? minVal = double.tryParse(minText);
      double? maxVal = double.tryParse(maxText);

      if (minVal != null && maxVal != null && minVal > maxVal) {
        return [
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: Row(
              children: [
                Icon(Icons.warning, size: 12, color: Colors.red),
                const SizedBox(width: 4),
                Text(
                  'Min price should be less than max price',
                  style: TextStyle(fontSize: 10, color: Colors.red),
                ),
              ],
            ),
          ),
        ];
      }
    }
    return [];
  }

// Add this method to auto-save room details
  void _autoSaveRoomDetails() {
    // Save to your backend/storage if needed
    print('Room details updated: ${_data['roomDetails']}');

    // Optional: Show auto-save indicator
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Price updated automatically'),
          backgroundColor: primaryColor.withOpacity(0.8),
          duration: Duration(seconds: 1),
        ),
      );
    }
  }

  // Detail Row
  Widget _buildDetailRow(String label, dynamic value) {
    if (!_hasValue(value)) return const SizedBox.shrink();

    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(label, style: TextStyle(fontSize: 12, color: lightText)),
          Text(
            value.toString(),
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w600,
              color: darkText,
            ),
          ),
        ],
      ),
    );
  }

