  String _formatInteger(dynamic value) {
    if (value == null) return '';
    if (value is int) return value.toString();
    if (value is double) return value.toInt().toString();
    if (value is String) {
      double? parsedDouble = double.tryParse(value);
      if (parsedDouble != null) return parsedDouble.toInt().toString();
      return value;
    }
    return value.toString();
  }

  String _formatPrice(dynamic value) {
    if (value == null) return '';
    if (value is double) {
      return value.toStringAsFixed(value.truncateToDouble() == value ? 0 : 2);
    }
    if (value is int) return value.toString();
    if (value is String) {
      double? parsed = double.tryParse(value);
      if (parsed != null) {
        return parsed.toStringAsFixed(
          parsed.truncateToDouble() == parsed ? 0 : 2,
        );
      }
      return value;
    }
    return value.toString();
  }

  String _formatTime(String time) {
    if (time.isEmpty) return 'Not set';

    try {
      if (time.contains(':')) {
        List<String> parts = time.split(':');
        if (parts.length >= 2) {
          int hour = int.parse(parts[0]);
          int minute = int.parse(parts[1].substring(0, 2));

          String period = hour >= 12 ? 'PM' : 'AM';
          int hour12 = hour % 12;
          if (hour12 == 0) hour12 = 12;

          return '${hour12.toString().padLeft(2, '0')}:${minute.toString().padLeft(2, '0')} $period';
        }
      }
    } catch (e) {
      return time;
    }
    return time;
  }

  bool _hasValue(dynamic value) {
    if (value == null) return false;
    if (value is String && value.isEmpty) return false;
    if (value is num && value == 0) return true;
    return true;
  }

  String _getRegistrationId() {
    final estateName = _data['estateName']?.toString() ?? 'ESTATE';
    final timestamp = DateTime.now().millisecondsSinceEpoch
        .toString()
        .substring(8);
    final namePrefix = estateName.length >= 3
        ? estateName.substring(0, 3).toUpperCase()
        : estateName.toUpperCase();
    return '7SOV-$namePrefix-$timestamp';
  }

  String _getUserFullName() {
    if (_data.containsKey('sovereignOwner') &&
        _data['sovereignOwner'].toString().isNotEmpty) {
      return _data['sovereignOwner'].toString();
    }
    if (_data.containsKey('authorizedAuthority') &&
        _data['authorizedAuthority'].toString().isNotEmpty) {
      return _data['authorizedAuthority'].toString();
    }
    return 'Sovereign Authority';
  }

  String _getUserEmail() {
    return _data['executiveEmail']?.toString() ?? 'Not provided';
  }



  String _getEstateName() {
    return _data['estateName']?.toString() ?? 'Estate';
  }

  String _getHotelType() {
    return _data['hotelCategory']?.toString() ?? '7-Star';
  }


  Widget _buildEditableSection({
    required String title,
    required IconData icon,
    required Map<String, bool> amenities,
    required String sectionId,
  }) {
    bool isEditMode = _editModes[sectionId] ?? false;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: borderColor),
        boxShadow: [
          BoxShadow(
            color: shadowColor,
            blurRadius: 20,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Header with Edit/Finish button
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: primarySoft,
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: Icon(icon, size: 16, color: primaryColor),
                  ),
                  const SizedBox(width: 12),
                  Text(
                    title,
                    style: TextStyle(
                      fontSize: 15,
                      fontWeight: FontWeight.w700,
                      color: darkText,
                      letterSpacing: -0.3,
                    ),
                  ),
                ],
              ),
              // Edit/Finish Button
              GestureDetector(
                onTap: () {
                  setState(() {
                    if (isEditMode) {
                      // Finish editing - save and exit edit mode
                      _autoSaveAmenities();
                      _editModes[sectionId] = false;
                    } else {
                      // Enter edit mode
                      _editModes[sectionId] = true;
                    }
                  });
                },
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color: isEditMode ? primaryColor : primarySoft,
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color: isEditMode ? Colors.transparent : primaryColor.withOpacity(0.2),
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(
                        isEditMode ? Icons.check : Icons.edit,
                        size: 14,
                        color: isEditMode ? Colors.white : primaryColor,
                      ),
                      const SizedBox(width: 4),
                      Text(
                        isEditMode ? 'Submit' : 'Edit',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: isEditMode ? Colors.white : primaryColor,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),

          // Amenities grid - SHOW ALL AMENITIES (both selected and unselected)
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: amenities.entries.map((entry) {
              bool isSelected = entry.value;
              return GestureDetector(
                onTap: isEditMode
                    ? () {
                  setState(() {
                    amenities[entry.key] = !isSelected;
                    // Auto-save only in edit mode
                    _autoSaveAmenities();
                  });
                }
                    : null, // No action in view mode
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 8,
                  ),
                  decoration: BoxDecoration(
                    gradient: isSelected
                        ? LinearGradient(
                      colors: [primaryColor, primaryColor.withOpacity(0.8)],
                    )
                        : null,
                    color: isSelected ? null : Colors.white,
                    borderRadius: BorderRadius.circular(25),
                    border: Border.all(
                      color: isSelected
                          ? Colors.transparent
                          : borderColor,
                      width: isSelected ? 0 : 1,
                    ),
                    boxShadow: isSelected
                        ? [
                      BoxShadow(
                        color: primaryColor.withOpacity(0.3),
                        blurRadius: 8,
                        offset: const Offset(0, 2),
                      ),
                    ]
                        : null,
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      if (isSelected)
                        Icon(
                          Icons.check_circle,
                          size: 14,
                          color: Colors.white,
                        )
                      else
                        Icon(
                          isEditMode ? Icons.circle_outlined : Icons.circle,
                          size: 14,
                          color: isEditMode ? lightText : borderColor,
                        ),
                      const SizedBox(width: 6),
                      Text(
                        entry.key,
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: isSelected ? FontWeight.w600 : FontWeight.w500,
                          color: isSelected ? Colors.white : darkText,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }).toList(),
          ),
        ],
      ),
    );
  }

