// Room Details - FIXED
  List<Widget> _buildRoomDetails() {
    List<Widget> widgets = [];
    final royalAccommodations = _data['royalAccommodations'];
    final selectedRoyalAccommodations = _data['selectedRoyalAccommodations'];

    print('Building room details - royalAccommodations: $royalAccommodations');
    print('selectedRoyalAccommodations: $selectedRoyalAccommodations');

    if (royalAccommodations is Map && selectedRoyalAccommodations is Map) {
      selectedRoyalAccommodations.forEach((type, isSelected) {
        if (isSelected == true && royalAccommodations.containsKey(type)) {
          final details = royalAccommodations[type];
          if (details is Map) {
            bool hasData = false;

            // Check each field properly
            if (details['units'] != null &&
                details['units'].toString().isNotEmpty &&
                details['units'] != 0) hasData = true;

            if (details['area'] != null &&
                details['area'].toString().isNotEmpty) hasData = true;

            if (details['maxGuests'] != null &&
                details['maxGuests'].toString().isNotEmpty &&
                details['maxGuests'] != 0) hasData = true;

            if (details['signatureFeatures'] != null &&
                details['signatureFeatures'].toString().isNotEmpty) hasData = true;

            if (details['avgNightlyRate'] != null &&
                details['avgNightlyRate'].toString().isNotEmpty &&
                details['avgNightlyRate'] != 0) hasData = true;

            if (hasData) {
              widgets.add(
                Container(
                  margin: const EdgeInsets.only(bottom: 12),
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: cardColor,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: borderColor),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            padding: const EdgeInsets.all(8),
                            decoration: BoxDecoration(
                              color: primarySoft,
                              borderRadius: BorderRadius.circular(10),
                            ),
                            child: Icon(
                              Icons.account_balance,
                              size: 16,
                              color: primaryColor,
                            ),
                          ),
                          const SizedBox(width: 12),
                          Text(
                            type.toString(),
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w700,
                              color: primaryColor,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),

                      if (_hasValue(details['units']) && details['units'] != 0)
                        _buildDetailRow('Number of Units', _formatInteger(details['units'])),

                      if (_hasValue(details['area']))
                        _buildDetailRow('Area', '${details['area']} sq m'),

                      if (_hasValue(details['maxGuests']) && details['maxGuests'] != 0)
                        _buildDetailRow('Max Guests', _formatInteger(details['maxGuests'])),

                      if (_hasValue(details['signatureFeatures']))
                        _buildDetailRow('Signature Features', details['signatureFeatures']),

                      if (_hasValue(details['avgNightlyRate']) && details['avgNightlyRate'] != 0)
                        _buildDetailRow('Avg Nightly Rate', '\$${_formatPrice(details['avgNightlyRate'])}'),

                      if (_hasValue(details['peakRate']) && details['peakRate'] != 0)
                        _buildDetailRow('Peak Rate', '\$${_formatPrice(details['peakRate'])}'),
                    ],
                  ),
                ),
              );
            }
          }
        }
      });
    }
    return widgets;
  }
