  String _formatInteger(dynamic value) {
    if (value == null) return '';
    if (value is int) return value.toString();
    if (value is double) return value.toInt().toString();
    if (value is String) {
      double? parsedDouble = double.tryParse(value);
      if (parsedDouble != null) return parsedDouble.toInt().toString();
      return value;
    }
    return value.toString();
  }

  String _formatPrice(dynamic value) {
    if (value == null) return '';
    if (value is double) {
      return value.toStringAsFixed(value.truncateToDouble() == value ? 0 : 2);
    }
    if (value is int) return value.toString();
    if (value is String) {
      double? parsed = double.tryParse(value);
      if (parsed != null) {
        return parsed.toStringAsFixed(
          parsed.truncateToDouble() == parsed ? 0 : 2,
        );
      }
      return value;
    }
    return value.toString();
  }

  String _formatTime(String time) {
    if (time.isEmpty) return 'Not set';
    try {
      if (time.contains(':')) {
        List<String> parts = time.split(':');
        if (parts.length >= 2) {
          int hour = int.parse(parts[0]);
          int minute = int.parse(parts[1].substring(0, 2));
          String period = hour >= 12 ? 'PM' : 'AM';
          int hour12 = hour % 12;
          if (hour12 == 0) hour12 = 12;
          return '${hour12.toString().padLeft(2, '0')}:${minute.toString().padLeft(2, '0')} $period';
        }
      }
    } catch (e) {
      return time;
    }
    return time;
  }

  bool _hasValue(dynamic value) {
    if (value == null) return false;
    if (value is String && value.isEmpty) return false;
    if (value is num && value == 0) return true;
    if (value is bool) return true;
    if (value is Map) return value.isNotEmpty;
    if (value is List) return value.isNotEmpty;
    return true;
  }

  String _getRegistrationId() {
    final propertyName = _data['propertyName']?.toString() ?? 'ELITE';
    final timestamp = DateTime.now().millisecondsSinceEpoch
        .toString()
        .substring(8);
    final namePrefix = propertyName.length >= 3
        ? propertyName.substring(0, 3).toUpperCase()
        : propertyName.toUpperCase();
    return 'GE-$namePrefix-$timestamp';
  }

  String _getUserFullName() {
    if (_data.containsKey('ubo') && _data['ubo'].toString().isNotEmpty) {
      return _data['ubo'].toString();
    }
    if (_data.containsKey('authorizedSignatory') &&
        _data['authorizedSignatory'].toString().isNotEmpty) {
      return _data['authorizedSignatory'].toString();
    }
    if (_data.containsKey('authorizedSignatoryName') &&
        _data['authorizedSignatoryName'].toString().isNotEmpty) {
      return _data['authorizedSignatoryName'].toString();
    }
    return 'Global Elite Authority';
  }

  String _getUserEmail() {
    return _data['executiveEmail']?.toString() ?? 'Not provided';
  }

  String _getUserPhone() {
    if (_data.containsKey('primaryContact')) {
      return _data['primaryContact'].toString();
    }
    return 'Not provided';
  }

  String _getPropertyName() {
    return _data['propertyName']?.toString() ?? 'Property';
  }

  String _getHotelType() {
    return _data['hotelCategory']?.toString() ?? 'Global Elite Luxury';
  }

