  // Tab 2: Executive Command - With Editable Phone
  Widget _buildExecutiveCommandTab() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          if (_data.containsKey('profilePhoto') &&
              _data['profilePhoto'] is Map &&
              _data['profilePhoto']['uploaded'] == true)
            Padding(
              padding: const EdgeInsets.only(bottom: 16),
              child: _buildPhotoTile(_data['profilePhoto']),
            ),

          // Executive Command Card with Phone Edit functionality
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(20),
            decoration: BoxDecoration(
              color: cardColor,
              borderRadius: BorderRadius.circular(24),
              border: Border.all(color: borderColor),
              boxShadow: [
                BoxShadow(
                  color: shadowColor,
                  blurRadius: 20,
                  offset: const Offset(0, 8),
                ),
                BoxShadow(
                  color: primaryColor.withOpacity(0.02),
                  blurRadius: 10,
                  offset: const Offset(0, 2),
                ),
              ],
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // Header with Title and Edit Button for Phone
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Row(
                      children: [
                        Container(
                          padding: const EdgeInsets.all(10),
                          decoration: BoxDecoration(
                            color: primarySoft,
                            borderRadius: BorderRadius.circular(14),
                          ),
                          child: Icon(Icons.account_balance, size: 18, color: primaryColor),
                        ),
                        const SizedBox(width: 12),
                        Text(
                          'Executive Command',
                          style: TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w700,
                            color: darkText,
                            letterSpacing: -0.3,
                          ),
                        ),
                      ],
                    ),
                    // Edit button for phone only
                    if (!_isEditingPhone)
                      GestureDetector(
                        onTap: () {
                          setState(() {
                            _isEditingPhone = true;
                            _phoneController.text = _getUserPhone();
                          });
                        },
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 12,
                            vertical: 6,
                          ),
                          decoration: BoxDecoration(
                            color: primarySoft,
                            borderRadius: BorderRadius.circular(20),
                            border: Border.all(color: primaryColor.withOpacity(0.2)),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Icon(
                                Icons.edit,
                                size: 14,
                                color: primaryColor,
                              ),
                              const SizedBox(width: 4),
                              Text(
                                'Edit Phone',
                                style: TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600,
                                  color: primaryColor,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                  ],
                ),
                const SizedBox(height: 16),

                // Command Info Fields
                if (_hasValue(_data['legalEntity']))
                  _buildInfoRow('Legal Entity Name', _data['legalEntity']),
                if (_hasValue(_data['ubo']))
                  _buildInfoRow('Ultimate Beneficial Owner (UBO)', _data['ubo']),
                if (_hasValue(_data['authorizedSignatory']))
                  _buildInfoRow('Authorized Signatory', _data['authorizedSignatory']),
                if (_hasValue(_data['designation']))
                  _buildInfoRow('Designation', _data['designation']),
                if (_hasValue(_data['generalManager']))
                  _buildInfoRow('General Manager', _data['generalManager']),
                if (_hasValue(_data['vipRelationsDirector']))
                  _buildInfoRow('VIP Relations Director', _data['vipRelationsDirector']),

                // Phone Number - Editable when in edit mode
                if (_isEditingPhone)
                  _buildEditablePhoneField()
                else
                  if (_hasValue(_data['primaryContact']))
                    _buildInfoRow('Primary Contact', _data['primaryContact']),

                // Save/Cancel buttons when editing phone
                if (_isEditingPhone)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 12),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.end,
                      children: [
                        TextButton(
                          onPressed: () {
                            setState(() {
                              _isEditingPhone = false;
                              _phoneController.text = _getUserPhone();
                            });
                          },
                          style: TextButton.styleFrom(
                            foregroundColor: lightText,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 16,
                              vertical: 8,
                            ),
                          ),
                          child: const Text('Cancel'),
                        ),
                        const SizedBox(width: 8),
                        ElevatedButton(
                          onPressed: _savePhoneChanges,
                          style: ElevatedButton.styleFrom(
                            backgroundColor: primaryColor,
                            foregroundColor: Colors.white,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 16,
                              vertical: 8,
                            ),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(20),
                            ),
                          ),
                          child: const Text('Save'),
                        ),
                      ],
                    ),
                  ),

                // Other non-editable fields
                if (_hasValue(_data['secondaryContact']))
                  _buildInfoRow('Secondary Contact', _data['secondaryContact']),
                if (_hasValue(_data['executiveEmail']))
                  _buildInfoRow('Executive Email', _data['executiveEmail']),
                if (_hasValue(_data['websitePortfolio']))
                  _buildInfoRow('Website / Portfolio', _data['websitePortfolio']),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // Tab 3: Location & Accommodations
  Widget _buildLocationAccommodationsTab() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          _buildGlassCard(
            title: 'Estate Location & Access Matrix',
            icon: Icons.location_on,
            children: [
              if (_hasValue(_data['addressLine1']))
                _buildInfoRow('Address Line 1', _data['addressLine1']),
              if (_hasValue(_data['addressLine2']))
                _buildInfoRow('Address Line 2', _data['addressLine2']),
              if (_hasValue(_data['city']))
                _buildInfoRow('City', _data['city']),
              if (_hasValue(_data['state']))
                _buildInfoRow('State / Province', _data['state']),
              if (_hasValue(_data['country']))
                _buildInfoRow('Country', _data['country']),
              if (_hasValue(_data['postalCode']))
                _buildInfoRow('Postal Code', _data['postalCode']),
              if (_hasValue(_data['nearestAirport']))
                _buildInfoRow('Nearest Airport', _data['nearestAirport']),
              if (_hasValue(_data['distanceFromAirport']))
                _buildInfoRow('Distance from Airport', '${_data['distanceFromAirport']} km'),
            ],
          ),
          // if (_hasValue(_data['privateAccessOptions']))
          //   Padding(
          //     padding: const EdgeInsets.only(top: 16),
          //     child: _buildAmenityCard('Private Access Options', _data['privateAccessOptions']),
          //   ),

          if (_privateAccessOptions.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildEditableSection(
                title: 'Private Access Options',
                icon: Icons.vpn_key,
                amenities: _privateAccessOptions,
                sectionId: 'privateAccess',
              ),
            ),
          Padding(
            padding: const EdgeInsets.only(top: 16),
            child: _buildGlassCard(
              title: 'Accommodation Matrix',
              icon: Icons.meeting_room,
              children: _buildRoomTypes(),
            ),
          ),
          ..._buildRoomDetails(),
          if (_hasValue(_data['rateEngineType']))
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildGlassCard(
                title: 'Rate Intelligence',
                icon: Icons.auto_awesome,
                children: [
                  _buildInfoRow('Rate Engine Type', _data['rateEngineType']),
                ],
              ),
            ),
          if (_hasValue(_data['checkInTime']) || _hasValue(_data['checkOutTime']))
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildGlassCard(
                title: 'Arrival & Departure Times',
                icon: Icons.access_time,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text('Check-In Time', style: _labelStyle),
                            const SizedBox(height: 4),
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 8,
                              ),
                              decoration: BoxDecoration(
                                color: Colors.grey[50],
                                borderRadius: BorderRadius.circular(8),
                                border: Border.all(color: borderColor),
                              ),
                              child: Row(
                                children: [
                                  Icon(Icons.access_time, size: 14, color: primaryColor),
                                  const SizedBox(width: 8),
                                  Text(
                                    _formatTime(_data['checkInTime']?.toString() ?? ''),
                                    style: _valueStyle,
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text('Check-Out Time', style: _labelStyle),
                            const SizedBox(height: 4),
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 8,
                              ),
                              decoration: BoxDecoration(
                                color: Colors.grey[50],
                                borderRadius: BorderRadius.circular(8),
                                border: Border.all(color: borderColor),
                              ),
                              child: Row(
                                children: [
                                  Icon(Icons.access_time, size: 14, color: primaryColor),
                                  const SizedBox(width: 8),
                                  Text(
                                    _formatTime(_data['checkOutTime']?.toString() ?? ''),
                                    style: _valueStyle,
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
        ],
      ),
    );
  }

