  // Tab 4: Ultra-Elite Facilities - EDITABLE with edit mode per section
  Widget _buildUltraEliteFacilitiesTab() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          // In-Suite Technology - With edit mode
          if (_inSuiteTechnology.isNotEmpty)
            _buildEditableSection(
              title: 'In-Suite Technology',
              icon: Icons.smart_toy,
              amenities: _inSuiteTechnology,
              sectionId: 'inSuiteTech',
            ),

          // Signature Luxury Features - With edit mode
          if (_signatureLuxuryFeatures.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildEditableSection(
                title: 'Signature Luxury Features',
                icon: Icons.workspace_premium,
                amenities: _signatureLuxuryFeatures,
                sectionId: 'signature',
              ),
            ),

          // Private Access Options - With edit mode
          if (_privateAccessOptions.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildEditableSection(
                title: 'Private Access Options',
                icon: Icons.vpn_key,
                amenities: _privateAccessOptions,
                sectionId: 'privateAccess',
              ),
            ),

          // Arrival Experience - With edit mode
          if (_arrivalExperience.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildEditableSection(
                title: 'Arrival Experience',
                icon: Icons.flight_takeoff,
                amenities: _arrivalExperience,
                sectionId: 'arrival',
              ),
            ),

          // Luxury Linen Brand (keep as is - not an amenity map)
          if (_hasValue(_data['luxuryLinenBrand']))
            Padding(
              padding: const EdgeInsets.only(top: 16),
              child: _buildGlassCard(
                title: 'Luxury Linen Brand',
                icon: Icons.bed,
                children: [
                  _buildInfoRow('Specified Brand', _data['luxuryLinenBrand']),
                ],
              ),
            ),
        ],
      ),
    );
  }

