          // Michelin-Star Count (keep as is - not an amenity map)
          if (_hasValue(_data['michelinCount']) && _data['michelinCount'] != 0)
            Padding(
              padding: const EdgeInsets.only(top: 8, bottom: 8),
              child: _buildInfoRow('Michelin-Star Restaurants', _formatInteger(_data['michelinCount'])),
            ),

          // Banquet Hall Capacity (keep as is)
          if (_hasValue(_data['banquetHallCapacity']) && _data['banquetHallCapacity'] != 0)
            Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: _buildInfoRow('Banquet Hall Capacity', '${_formatInteger(_data['banquetHallCapacity'])} seats'),
            ),

          // Global Event Hosting (keep as is)
          if (_data.containsKey('globalEventHosting'))
            Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: _buildStatusRow('Global Event Hosting', _data['globalEventHosting']),
