  // Room Types
  List<Widget> _buildRoomTypes() {
    List<Widget> widgets = [];
    final selectedAccommodationTypes = _data['selectedAccommodationTypes'];

    if (selectedAccommodationTypes is Map) {
      final selected = selectedAccommodationTypes.entries
          .where((e) => _getBooleanValue(e.value))
          .map((e) => e.key)
          .toList();

      if (selected.isNotEmpty) {
        widgets.add(
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: Wrap(
              spacing: 8,
              runSpacing: 8,
              children: selected
                  .map(
                    (type) => Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: [primaryColor, goldColor],
                    ),
                    borderRadius: BorderRadius.circular(20),
                    boxShadow: [
                      BoxShadow(
                        color: primaryColor.withOpacity(0.2),
                        blurRadius: 8,
                        offset: const Offset(0, 2),
                      ),
                    ],
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      ...List.generate(
                        6,
                            (index) => Icon(
                          Icons.star,
                          size: 8,
                          color: goldColor,
                        ),
                      ),
                      const SizedBox(width: 6),
                      Text(
                        type.toString(),
                        style: const TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: Colors.white,
                        ),
                      ),
                    ],
                  ),
                ),
              )
                  .toList(),
            ),
          ),
        );
      }
    }
    return widgets;
  }

