                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            padding: const EdgeInsets.all(8),
                            decoration: BoxDecoration(
                              color: primarySoft,
                              borderRadius: BorderRadius.circular(10),
                            ),
                            child: Icon(
                              Icons.hotel,
                              size: 16,
                              color: primaryColor,
                            ),
                          ),
                          const SizedBox(width: 12),
                          Text(
                            type.toString(),
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w700,
                              color: primaryColor,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),
                      if (_hasValue(details['units']) && details['units'] != 0)
                        _buildDetailRow('Number of Units', _formatInteger(details['units'])),
                      if (_hasValue(details['size']))
                        _buildDetailRow('Size', '${details['size']} sq ft'),
                      if (_hasValue(details['occupancy']) && details['occupancy'] != 0)
                        _buildDetailRow('Max Occupancy', _formatInteger(details['occupancy'])),
                      if (_hasValue(details['bedType']))
                        _buildDetailRow('Bed Type', details['bedType']),
                      if (_hasValue(details['avgNightlyRate']) && details['avgNightlyRate'] != 0)
                        _buildDetailRow('Avg Nightly Rate', '\$${_formatPrice(details['avgNightlyRate'])}'),
                      if (_hasValue(details['peakRate']) && details['peakRate'] != 0)
                        _buildDetailRow('Peak Rate', '\$${_formatPrice(details['peakRate'])}'),
                    ],
                  ),
                ),
              );
            }
          }
        }
      });
    }
    return widgets;
  }

