// Uploaded Documents - COMPLETELY FIXED
  List<Widget> _buildUploadedDocuments() {
    List<Widget> widgets = [];

    // Check multiple possible keys where documents might be stored
    dynamic documents;

    if (_data.containsKey('requiredDocuments')) {
      documents = _data['requiredDocuments'];
      print('Found requiredDocuments: ${documents.runtimeType}');
    } else if (_data.containsKey('sovereignCredentials')) {
      documents = _data['sovereignCredentials'];
      print('Found sovereignCredentials: ${documents.runtimeType}');
    } else if (_data.containsKey('uploadedFiles')) {
      documents = _data['uploadedFiles'];
      print('Found uploadedFiles: ${documents.runtimeType}');
    } else {
      // Try to find any map that might contain document info
      _data.forEach((key, value) {
        if (value is Map &&
            (value.containsKey('uploaded') ||
                value.containsKey('name') ||
                value.containsKey('path'))) {
          print('Found potential document container at key: $key');
          documents = value;
        }
      });
    }

    if (documents == null) {
      print('No document container found');
      return [Container(
        padding: const EdgeInsets.all(16),
        child: Text(
          'No documents uploaded',
          style: TextStyle(color: lightText, fontSize: 14),
        ),
      )];
    }

    if (documents is! Map) {
      print('Documents is not a Map, it is: ${documents.runtimeType}');
      return [Container(
        padding: const EdgeInsets.all(16),
        child: Text(
          'Document data is in unexpected format',
          style: TextStyle(color: lightText, fontSize: 14),
        ),
      )];
    }

    print('Processing documents map with keys: ${documents.keys.toList()}');

    documents.forEach((key, value) {
      print('Checking document: $key, value: $value');

      if (value is Map) {
        // Check if this document is uploaded
        bool isUploaded = false;

        if (value.containsKey('uploaded')) {
          isUploaded = _getBooleanValue(value['uploaded']);
        } else if (value.containsKey('isUploaded')) {
          isUploaded = _getBooleanValue(value['isUploaded']);
        }

        // Also check if there's a name or path (indicating it might be uploaded)
        bool hasName = value.containsKey('name') &&
            value['name'] != null &&
            value['name'].toString().isNotEmpty;

        if (isUploaded || hasName) {
          String fileName = value['name']?.toString() ?? 'Document';
          String fileSize = value['size']?.toString() ?? '';

          print('Adding uploaded document: $key - $fileName');

          widgets.add(
            Container(
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: primarySoft,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: primaryColor.withOpacity(0.15)),
              ),
              child: Row(
                children: [
                  Icon(Icons.check_circle, size: 16, color: primaryColor),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          key,
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w600,
                            color: darkText,
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          fileName,
                          style: TextStyle(fontSize: 11, color: lightText),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                        ),
                        if (fileSize.isNotEmpty)
                          Text(
                            '${(int.tryParse(fileSize) ?? 0) ~/ 1024} KB',
                            style: TextStyle(fontSize: 10, color: lightText),
                          ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          );
        } else {
          print('Document $key is not uploaded');
        }
      } else {
        print('Document $key is not a Map');
      }
    });

    if (widgets.isEmpty) {
      widgets.add(
        Container(
          padding: const EdgeInsets.all(16),
          child: Text(
            'No uploaded documents found',
            style: TextStyle(color: lightText, fontSize: 14),
          ),
        ),
      );
    }

    return widgets;
  }

  // Helper method to convert any value to boolean
  bool _getBooleanValue(dynamic value) {
    if (value == null) return false;
    if (value is bool) return value;
    if (value is int) return value == 1;
    if (value is String) {
      return value.toLowerCase() == 'true' ||
          value.toLowerCase() == 'yes' ||
          value == '1';
    }
    return false;
  }
  // Photo Tile
// Photo Tile
  Widget _buildPhotoTile(Map<String, dynamic> photoInfo) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: cardColor,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: borderColor),
      ),
      child: Row(
        children: [
          Container(
            width: 50,
            height: 50,
            decoration: BoxDecoration(
              gradient: LinearGradient(
                colors: [primaryColor, goldColor],
              ),
              borderRadius: BorderRadius.circular(14),
            ),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(14),
              child: photoInfo['path'] != null
                  ? Image.file(
                File(photoInfo['path']),
                fit: BoxFit.cover,
              )
                  : const Center(
                child: Icon(Icons.person, color: Colors.white, size: 24),
              ),
            ),
          ),
          const SizedBox(width: 16),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'Profile Photo',
                  style: TextStyle(fontSize: 14, fontWeight: FontWeight.w600),
                ),
                const SizedBox(height: 2),
                Text(
                  photoInfo['name'] ?? 'Uploaded successfully',
                  style: TextStyle(fontSize: 12, color: lightText),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ],
            ),
          ),
          Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: primarySoft,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Icon(Icons.check_circle, size: 18, color: primaryColor),
          ),
        ],
      ),
    );
  }

  // Digital Signature Tile
  Widget _buildDigitalSignatureTile() {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: primarySoft,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: primaryColor.withOpacity(0.2)),
      ),
      child: Row(
        children: [
          Container(
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: cardColor,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Icon(Icons.draw, size: 20, color: primaryColor),
          ),
          const SizedBox(width: 16),
          const Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Digital Signature',
                  style: TextStyle(fontSize: 14, fontWeight: FontWeight.w600),
                ),
                SizedBox(height: 2),
                Text('Saved successfully', style: TextStyle(fontSize: 12)),
              ],
            ),
          ),
          Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: cardColor,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Icon(Icons.check_circle, size: 18, color: primaryColor),
          ),
        ],
      ),
    );
  }

  // Helper method to format date
  String _formatDate(dynamic date) {
    if (date == null) return '';
    if (date is DateTime) {
      return '${date.day}/${date.month}/${date.year}';
    } else if (date is String) {
      try {
        DateTime parsedDate = DateTime.parse(date);
        return '${parsedDate.day}/${parsedDate.month}/${parsedDate.year}';
      } catch (e) {
        return date;
      }
    }
    return date.toString();
  }

  // Helper method to mask account number
  String _maskAccountNumber(String accountNumber) {
    if (accountNumber.length <= 4) return accountNumber;
    return 'XXXX XXXX ${accountNumber.substring(accountNumber.length - 4)}';
  }

  // Style getters
  TextStyle get _labelStyle =>
      TextStyle(fontSize: 13, color: lightText, fontWeight: FontWeight.w500);

  TextStyle get _valueStyle =>
      TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: darkText);
}








