class _VillaListScreenState extends State<VillaListScreen> {
  List<Map<String, dynamic>> _registeredVillas = [];
  bool _isLoading = true;

  @override
  void initState() {
    super.initState();
    _loadVillasFromStorage();
    _debugPrintStorage();
  }

  Future<void> _debugPrintStorage() async {
    final prefs = await SharedPreferences.getInstance();
    final String? userDataString = prefs.getString('user_${widget.userEmail}_data');

    if (userDataString != null) {
      Map<String, dynamic> userData = jsonDecode(userDataString);
      print('=== DEBUG STORAGE ===');
      print('User email: ${widget.userEmail}');
      print('Data keys: ${userData.keys.toList()}');

      if (userData.containsKey('villlas')) {
        List<dynamic> villas = userData['villlas'];
        print('Number of villas: ${villas.length}');
        for (var i = 0; i < villas.length; i++) {
          Map<String, dynamic> villa = Map<String, dynamic>.from(villas[i]);
          print('Villa $i - ID: ${villa['id']}, Name: ${villa['basicInfo']?['villaName'] ?? villa['villaName']}');
        }
      }
    } else {
      print('No data found for user: ${widget.userEmail}');
    }
  }

  Future<void> _loadVillasFromStorage() async {
    setState(() => _isLoading = true);

    try {
      final prefs = await SharedPreferences.getInstance();
      final String usersJson = prefs.getString('registered_users') ?? '[]';
      final List<dynamic> usersList = jsonDecode(usersJson);

      print('=== LOADING VILLAS ===');
      print('User Email: ${widget.userEmail}');

      // Find the user
      Map<String, dynamic>? userData;
      for (var user in usersList) {
        if (user is Map && user['email'] == widget.userEmail) {
          userData = Map<String, dynamic>.from(user);
          break;
        }
      }

      if (userData != null) {
        print('Found user data with keys: ${userData.keys.toList()}');
        _extractVillas(userData);
      } else {
        print('User not found in registered_users');
        _extractVillas(widget.userData);
      }

    } catch (e) {
      print('Error loading villas: $e');
      _extractVillas(widget.userData);
    } finally {
      setState(() => _isLoading = false);
    }
  }



