  void _extractVillas(Map<String, dynamic> userData) {
    try {
      print('=== EXTRACTING VILLAS ===');
      print('User data keys: ${userData.keys.toList()}');
      print('Removed Villa ID: ${widget.removedVillaId}');

      _registeredVillas.clear();

      // Check for villas list (multiple villas)
      if (userData.containsKey('villlas') && userData['villlas'] is List) {
        List<dynamic> villasList = userData['villlas'] as List;
        print('Found villas list with ${villasList.length} villas');

        for (var villa in villasList) {
          if (villa is Map) {
            Map<String, dynamic> villaMap = Map<String, dynamic>.from(villa);

            // TRY TO GET ID FROM MULTIPLE LOCATIONS
            String villaId = '';

            // Check top-level id
            if (villaMap.containsKey('id') && villaMap['id'] != null) {
              villaId = villaMap['id'].toString();
            }
            // Check in basicInfo
            else if (villaMap.containsKey('basicInfo') && villaMap['basicInfo'] is Map) {
              final basicInfo = villaMap['basicInfo'] as Map;
              if (basicInfo.containsKey('id') && basicInfo['id'] != null) {
                villaId = basicInfo['id'].toString();
              }
            }

            print('Found villa ID: "$villaId"');

            // Skip if this is the villa that was removed
            if (widget.removedVillaId != null &&
                widget.removedVillaId!.isNotEmpty &&
                villaId.isNotEmpty &&
                villaId == widget.removedVillaId) {
              print('SKIPPING removed villa with ID: $villaId');
              continue;
            }

            // Get villa name from the correct location
            String villaName = '';
            if (villaMap.containsKey('basicInfo') && villaMap['basicInfo'] is Map) {
              Map<String, dynamic> basicInfo = villaMap['basicInfo'];
              if (basicInfo.containsKey('villaName') && basicInfo['villaName'].toString().isNotEmpty) {
                villaName = basicInfo['villaName'].toString();
              }
            } else if (villaMap.containsKey('villaName') && villaMap['villaName'].toString().isNotEmpty) {
              villaName = villaMap['villaName'].toString();
            } else if (villaMap.containsKey('propertyName') && villaMap['propertyName'].toString().isNotEmpty) {
              villaName = villaMap['propertyName'].toString();
            } else {
              villaName = 'Unknown Villa';
            }

            // Get property type
            String propertyType = '';
            if (villaMap.containsKey('propertyDetails') && villaMap['propertyDetails'] is Map) {
              Map<String, dynamic> propertyDetails = villaMap['propertyDetails'];
              if (propertyDetails.containsKey('propertyType') && propertyDetails['propertyType'].toString().isNotEmpty) {
                propertyType = propertyDetails['propertyType'].toString();
              }
            } else if (villaMap.containsKey('propertyTypeValue') && villaMap['propertyTypeValue'].toString().isNotEmpty) {
              propertyType = villaMap['propertyTypeValue'].toString();
            } else if (villaMap.containsKey('propertyType') && villaMap['propertyType'].toString().isNotEmpty) {
              propertyType = villaMap['propertyType'].toString();
            } else {
              propertyType = 'Villa';
            }

            print('Adding villa: $villaName ($propertyType) with ID: $villaId');

            _registeredVillas.add({
              'id': villaId,
              'name': villaName,
              'propertyType': propertyType,
              'data': villaMap,
              'registrationDate': villaMap['registeredAt']?.toString() ??
                  DateTime.now().toIso8601String(),
            });
          }
        }
      }

      print('Total villas extracted: ${_registeredVillas.length}');
      for (var villa in _registeredVillas) {
        print('Villa: ${villa['name']}, ID: ${villa['id']}');
      }
    } catch (e) {
      print('Error extracting villas: $e');
    }
  }
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF9FAFB),
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        leading: IconButton(
          icon: Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: Colors.grey.shade100,
              shape: BoxShape.circle,
            ),
            child: const Icon(
              Icons.arrow_back,
              color: Color(0xFF1F2937),
              size: 20,
            ),
          ),
          onPressed: () => Navigator.pop(context),
        ),
        title: const Text(
          'My Villas List',
          style: TextStyle(
            color: Color(0xFF1F2937),
            fontSize: 20,
            fontWeight: FontWeight.w700,
          ),
        ),
        actions: [
          Padding(
            padding: const EdgeInsets.only(right: 16),
            child: ElevatedButton.icon(
              onPressed: () {
                Navigator.push(
                  context,
                  MaterialPageRoute(builder: (context) => WelcomeScreen()),
                );
              },
              icon: const Icon(Icons.add, size: 18),
              label: const Text('New Register'),
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF00897B),
                foregroundColor: Colors.white,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(30),
                ),
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 10,
                ),
              ),
            ),
          ),
        ],
      ),
      body: _isLoading
          ? const Center(child: CircularProgressIndicator())
          : _registeredVillas.isEmpty
          ? _buildEmptyState()
          : ListView.builder(
        padding: const EdgeInsets.all(13),
        itemCount: _registeredVillas.length,
        itemBuilder: (context, index) {
          final villa = _registeredVillas[index];
          return _buildVillaCard(villa);
        },
      ),
    );
  }

  Widget _buildEmptyState() {
    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Container(
            width: 120,
            height: 120,
            decoration: BoxDecoration(
              color: const Color(0xFF00897B).withOpacity(0.1),
              shape: BoxShape.circle,
            ),
            child: Icon(
              Icons.villa,
              size: 50,
              color: const Color(0xFF00897B).withOpacity(0.5),
            ),
          ),
          const SizedBox(height: 24),
          const Text(
            'No Villas Registered',
            style: TextStyle(
              fontSize: 18,
              fontWeight: FontWeight.w700,
              color: Color(0xFF1F2937),
            ),
          ),
          const SizedBox(height: 8),
          Text(
            'Register your first villa to get started',
            style: TextStyle(fontSize: 14, color: const Color(0xFF6B7280)),
          ),
          const SizedBox(height: 24),
          ElevatedButton(
            onPressed: () {
              Navigator.push(
                context,
                MaterialPageRoute(builder: (context) => WelcomeScreen()),
              );
            },
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF00897B),
              foregroundColor: Colors.white,
              padding: const EdgeInsets.symmetric(horizontal: 32, vertical: 16),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(30),
              ),
            ),
            child: const Text('Register Villa'),
          ),
        ],
      ),
    );
  }

  Widget _buildVillaCard(Map<String, dynamic> villa) {
    return GestureDetector(
      onTap: () {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (context) => VillaRegistrationDetailsScreen(
              registrationData: villa['data'],
               villaId: villa['id'],
              // villaId: widget._registeredVillas['id']?.toString(),
              villaIndex: _registeredVillas.indexOf(villa),

            ),
          ),
        );
      },
      child: Container(
        margin: const EdgeInsets.only(bottom: 16),
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(20),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.03),
              blurRadius: 10,
              offset: const Offset(0, 4),
            ),
          ],
        ),
        child: Row(
          children: [
            Container(
              width: 60,
              height: 60,
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: [const Color(0xFF00897B), const Color(0xFF00897B).withOpacity(0.7)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
                borderRadius: BorderRadius.circular(16),
              ),
              child: const Center(
                child: Icon(Icons.villa, color: Colors.white, size: 30),
              ),
            ),
            const SizedBox(width: 16),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          villa['name'],
                          style: const TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFF1F2937),
                          ),
                        ),
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 10,
                          vertical: 4,
                        ),
