  Widget _buildHotelCard(Map<String, dynamic> hotel) {
    final category = hotel['category'] as String;
    final categoryColor = _getCategoryColor(category);

    return GestureDetector(

      onTap: () {
        print('Comparing: "$category" == "Global Elite Luxury" = ${category == 'Global Elite Luxury'}');
        if (category == '2-Star') {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) =>
                  TwoStarHotelDetailsScreen(registrationData: hotel['data']),
            ),
          );
        } else if (category == '3-Star') {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) =>
                  ThreeStarHotelDetailsScreen(registrationData: hotel['data']),
            ),
          );
        } else if (category == '4-Star') {

          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) => FourStarHotelDetailsScreen(
                registrationData: hotel['data'],
              ),
            ),
          );
        }  else if (category == '5-Star') {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) =>
                  FiveStarHotelDetailsScreen(registrationData: hotel['data']),
            ),
          );
        }  else if (category == '6-Star') {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) =>
                  SixStarHotelDetailsScreen(registrationData: hotel['data']),
            ),
          );
        }  else if (category == '7-Star') {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) =>
                  SevenStarHotelDetailsScreen(registrationData: hotel['data']),
            ),
          );
        } else if (category.toLowerCase().contains('global elite') ||
            category.toLowerCase().contains('global elite luxury')) {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) => GlobalEliteLuxuryHotelDetailsScreen(
                registrationData: hotel['data'],
              ),
            ),
          );
        } else {

          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) => HotelRegistrationDetailsScreen(
                registrationData: hotel['data'],
              ),
            ),
          );
        }
      },
      child: Container(
        margin: const EdgeInsets.only(bottom: 16),
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(20),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.03),
              blurRadius: 10,
              offset: const Offset(0, 4),
            ),
          ],
        ),
        child: Row(
          children: [

            Container(
              width: 60,
              height: 60,
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: [categoryColor, categoryColor.withOpacity(0.7)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
                borderRadius: BorderRadius.circular(16),
              ),
              child: Center(
                child: Icon(Icons.home_work, color: Colors.white, size: 30),
              ),
            ),
            const SizedBox(width: 16),

            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          hotel['name'],
                          style: const TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFF1F2937),
                          ),
                        ),
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 10,
                          vertical: 4,
                        ),
                        decoration: BoxDecoration(
                          color: categoryColor.withOpacity(0.1),
                          borderRadius: BorderRadius.circular(20),
                          border: Border.all(
                            color: categoryColor.withOpacity(0.3),
                          ),
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            if (category.contains('Star'))
                              ...List.generate(
                                _getStarCount(category),
                                (index) => Icon(
                                  Icons.star,
                                  size: 10,
                                  color: categoryColor,
                                ),
                              ),
                            if (!category.contains('Star'))
                              Text(
                                category,
                                style: TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w600,
                                  color: categoryColor,
                                ),
                              ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  Text(
                    hotel['type'],
                    style: TextStyle(fontSize: 13, color: lightText),
                  ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 8,
                          vertical: 4,
                        ),
                        decoration: BoxDecoration(
                          color: Colors.grey.shade100,
                          borderRadius: BorderRadius.circular(12),
                        ),
                        child: Text(
                          'ID: ${hotel['id']}',
                          style: TextStyle(
                            fontSize: 10,
                            color: lightText,
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Icon(Icons.calendar_today, size: 12, color: lightText),
                      const SizedBox(width: 4),
                      Text(
                        _formatDate(hotel['registrationDate']),
                        style: TextStyle(fontSize: 10, color: lightText),
                      ),
                    ],
                  ),
                ],
              ),
            ),
            // Arrow Icon
            Container(
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                color: categoryColor.withOpacity(0.1),
                shape: BoxShape.circle,
              ),
              child: Icon(
                Icons.arrow_forward_rounded,
                color: categoryColor,
                size: 20,
              ),
            ),
          ],
        ),
      ),
    );
  }

  int _getStarCount(String category) {
    if (category.contains('2')) return 2;
    if (category.contains('3')) return 3;
    if (category.contains('4')) return 4;
    if (category.contains('5')) return 5;
    if (category.contains('6')) return 6;
    if (category.contains('7')) return 7;
    return 0;
  }

  String _formatDate(String dateString) {
    try {
      final date = DateTime.parse(dateString);
      return '${date.day}/${date.month}/${date.year}';
    } catch (e) {
      return dateString;
    }
  }
}

