  Widget _buildPropertyBox({
    required String propertyType,
    required IconData icon,
    required Color color,
    required bool isRegistered,
  }) {
    return GestureDetector(
      onTap: isRegistered
          ? () => _navigateToPropertyDetails(propertyType.toLowerCase())
          : null,
      child: Container(
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(20),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.03),
              blurRadius: 10,
              offset: const Offset(0, 5),
            ),
          ],
        ),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // Icon with modern container
            Container(
              width: 50,
              height: 50,
              decoration: BoxDecoration(
                gradient: RadialGradient(
                  center: Alignment.center,
                  radius: 0.8,
                  colors: isRegistered
                      ? [color.withOpacity(0.2), Colors.white]
                      : [Colors.grey.shade100, Colors.white],
                ),
                shape: BoxShape.circle,
              ),
              child: Icon(
                icon,
                size: 24,
                color: isRegistered ? color : Colors.grey.shade400,
              ),
            ),

            const SizedBox(height: 12),

            // Property type
            Text(
              propertyType,
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w500,
                color: isRegistered ? Colors.black87 : Colors.grey.shade500,
              ),
            ),

            const SizedBox(height: 8),

            // Custom indicator
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
              decoration: BoxDecoration(
                color: isRegistered ? color.withOpacity(0.1) : Colors.grey.shade100,
                borderRadius: BorderRadius.circular(30),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Container(
                    width: 6,
                    height: 6,
                    decoration: BoxDecoration(
                      color: isRegistered ? Colors.green : Colors.grey.shade400,
                      shape: BoxShape.circle,
                    ),
                  ),
                  const SizedBox(width: 4),
                  Text(
                    isRegistered ? 'Registered' : 'New',
                    style: TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w500,
                      color: isRegistered ? Colors.green.shade700 : Colors.grey.shade600,
                    ),
                  ),
                ],
