class TwoStarHotelDashboard extends StatefulWidget {
  final String hotelName;
  final String ownerName;
  final String mobileNumber;
  final String email;
  final String addressLine1;
  final String addressLine2;
  final String city;
  final String district;
  final String state;
  final String pinCode;
  final String gstNumber;
  final String fssaiLicense;
  final String tradeLicense;
  final String aadharNumber;
  final String panNumber;
  final String accountHolderName;
  final String bankName;
  final String accountNumber;
  final String ifscCode;
  final String branch;
  final String accountType;
  final int totalRooms;
  final Map<String, dynamic> personPhotoInfo;
  final Map<String, dynamic> registrationData;

  const TwoStarHotelDashboard({
    Key? key,
    required this.hotelName,
    required this.ownerName,
    required this.mobileNumber,
    required this.email,
    required this.addressLine1,
    this.addressLine2 = '',
    required this.city,
    required this.district,
    required this.state,
    required this.pinCode,
    this.gstNumber = '',
    this.fssaiLicense = '',
    this.tradeLicense = '',
    this.aadharNumber = '',
    this.panNumber = '',
    this.accountHolderName = '',
    this.bankName = '',
    this.accountNumber = '',
    this.ifscCode = '',
    this.branch = '',
    this.accountType = '',
    required this.totalRooms,
    required this.personPhotoInfo,
    required this.registrationData,
  }) : super(key: key);

  @override
  State<TwoStarHotelDashboard> createState() => _TwoStarHotelDashboardState();
}

class _TwoStarHotelDashboardState extends State<TwoStarHotelDashboard> {
  int _selectedIndex = 0;


  final Color primaryColor = const Color(0xFF6B8E23);
  final Color primaryLight = const Color(0xFF6B8E23).withOpacity(0.8);
  final Color primarySoft = const Color(0xFF6B8E23).withOpacity(0.1);
  final Color primaryMedium = const Color(0xFF6B8E23).withOpacity(0.05);

  final Color secondaryColor = const Color(0xFF4A6FA5);
  final Color accentColor = const Color(0xFF6BCF7F);
  final Color bgColor = const Color(0xFFF9FAFB);
  final Color cardBg = Colors.white;
  final Color darkText = const Color(0xFF111827);
  final Color lightText = const Color(0xFF6B7280);
  final Color borderColor = const Color(0xFFE5E7EB);
  final Color successColor = const Color(0xFF10B981);
  final Color warningColor = const Color(0xFFF59E0B);
  final Color dangerColor = const Color(0xFFEF4444);

  String _selectedMonth = 'January';
  String _selectedRoomType = 'All';
  String _selectedGraphFilter = 'Daily';
  List<String> _months = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];
  List<String> _bookingStatuses = [
    'Confirmed', 'Pending', 'Cancelled', 'Completed',
  ];
  List<Map<String, dynamic>> _roomTypeData = [];
  DateTime _selectedStartDate = DateTime.now().subtract(const Duration(days: 7));
  DateTime _selectedEndDate = DateTime.now();


  final List<String> _roomTypesList = [
    'Standard',
    'Deluxe',
    'Family Room',
    'Executive',
  ];

  @override
  void initState() {
    super.initState();
    _initializeRoomData();
  }

  void _initializeRoomData() {
    final roomDetails = widget.registrationData['roomDetails'] ?? {};
    _roomTypeData.clear();

    if (roomDetails.isNotEmpty) {
      roomDetails.forEach((type, details) {
        int totalRooms = int.tryParse(details['rooms']?.toString() ?? '0') ?? 0;
        double price = double.tryParse(details['price']?.toString() ?? '0') ?? 0;
        bool isAC = details['ac'] ?? false;
        int occupancy = int.tryParse(details['occupancy']?.toString() ?? '0') ?? 2;

        int acRooms = isAC ? totalRooms : 0;
        int nonAcRooms = !isAC ? totalRooms : 0;

        int availableAC = isAC ? (totalRooms * 0.4).round() : 0;
        int bookedAC = isAC ? (totalRooms * 0.5).round() : 0;
        int maintenanceAC = isAC ? (totalRooms * 0.1).round() : 0;

        int availableNonAC = !isAC ? (totalRooms * 0.4).round() : 0;
        int bookedNonAC = !isAC ? (totalRooms * 0.5).round() : 0;
        int maintenanceNonAC = !isAC ? (totalRooms * 0.1).round() : 0;

        _roomTypeData.add({
          'type': type,
          'total': totalRooms,
          'price': price,
          'occupancy': occupancy,
          'isAC': isAC,
          'acRooms': acRooms,
          'nonAcRooms': nonAcRooms,
          'availableAC': availableAC,
          'bookedAC': bookedAC,
          'maintenanceAC': maintenanceAC,
          'availableNonAC': availableNonAC,
          'bookedNonAC': bookedNonAC,
          'maintenanceNonAC': maintenanceNonAC,
          'totalAvailable': availableAC + availableNonAC,
          'totalBooked': bookedAC + bookedNonAC,
          'totalMaintenance': maintenanceAC + maintenanceNonAC,
        });
      });
    } else {
      // Generate sample data if no room details available
      _generateSampleRoomData();
    }
  }

  void _generateSampleRoomData() {
    _roomTypeData = [
      {
        'type': 'Standard',
        'total': 20,
        'price': 2500.0,
