  Color _getStatusColor(String status) {
    switch (status) {
      case 'Confirmed':
        return successColor;
      case 'Pending':
        return warningColor;
      case 'Cancelled':
        return dangerColor;
      case 'Completed':
        return secondaryColor;
      default:
        return primaryColor;
    }
  }

