    // Sovereign Amenities
    this.arrivalInfrastructure = const {},
    this.inResidenceSystems = const {},
    this.signatureRoyalAmenities = const {},
    this.arrivalCeremonialProtocols = const {},
    this.gastronomicSupremacy = const {},
    this.wellnessDominion = const {},
