  void _initializeRoomData() {
    final royalAccommodations = widget.registrationData['royalAccommodations'] ?? {};
    _roomTypeData.clear();

    if (royalAccommodations.isNotEmpty) {
      royalAccommodations.forEach((type, details) {
        int totalUnits = int.tryParse(details['units']?.toString() ?? '0') ?? 0;
        double avgRate = double.tryParse(details['avgNightlyRate']?.toString() ?? '0') ?? 0;
        int maxGuests = int.tryParse(details['maxGuests']?.toString() ?? '0') ?? 2;

        // For 7-star, all accommodations are ultra-luxury with highest standards
        int availableUnits = (totalUnits * 0.4).round();
        int bookedUnits = (totalUnits * 0.55).round();
        int maintenanceUnits = totalUnits - availableUnits - bookedUnits;

        _roomTypeData.add({
          'type': type,
          'total': totalUnits,
          'price': avgRate,
          'occupancy': maxGuests,
          'isAC': true, // All 7-star accommodations have climate control
          'acRooms': totalUnits,
          'nonAcRooms': 0,
          'availableAC': availableUnits,
          'bookedAC': bookedUnits,
          'maintenanceAC': maintenanceUnits,
          'availableNonAC': 0,
          'bookedNonAC': 0,
          'maintenanceNonAC': 0,
          'totalAvailable': availableUnits,
          'totalBooked': bookedUnits,
          'totalMaintenance': maintenanceUnits,
        });
      });
    } else {
      _generateSampleRoomData();
    }
  }

