  Map<String, List<double>> _generateWaveData(String roomType) {
    Map<String, List<double>> data = {};

    for (String type in _roomTypesList) {
      if (roomType == 'All' || roomType == type) {
        List<double> wavePoints = [];
        int days = 30;

        for (int i = 0; i < days; i++) {
          double baseValue = 0;
          switch (type) {
            case 'Imperial Chamber':
              baseValue = 8;
              break;
            case 'Royal Suite':
              baseValue = 6;
              break;
            case 'Crown Residence':
              baseValue = 4;
              break;
            case 'Presidential Palace Suite':
              baseValue = 3;
              break;
            case 'Private Kingdom Villa':
              baseValue = 2;
              break;
          }

          double variation = sin(i * 0.3) * 4 + cos(i * 0.5) * 2;
          double trend = i * 0.15;
          double noise = (Random().nextDouble() * 2) - 1;

          wavePoints.add(baseValue + variation + trend + noise);
        }
        data[type] = wavePoints;
      }
    }

    if (roomType == 'All') {
      List<double> combinedData = [];
      int days = 30;

      for (int i = 0; i < days; i++) {
        double combinedValue = 0;
        data.forEach((type, wavePoints) {
          combinedValue += wavePoints[i];
        });
        combinedData.add(combinedValue);
      }
      data['All'] = combinedData;
    }

    return data;
  }

  Widget _buildBookingInsightsGraph() {
    Map<String, List<double>> waveData = _generateWaveData(_selectedRoomType);
    List<double> currentWaveData =
        waveData[_selectedRoomType] ?? waveData['All'] ?? [];

    double maxValue = currentWaveData.isNotEmpty ? currentWaveData.reduce((a, b) => a > b ? a : b) : 0;
    double minValue = currentWaveData.isNotEmpty ? currentWaveData.reduce((a, b) => a < b ? a : b) : 0;

    double average = currentWaveData.isNotEmpty
        ? currentWaveData.reduce((a, b) => a + b) / currentWaveData.length
        : 0;
    double currentValue = currentWaveData.isNotEmpty ? currentWaveData.last : 0;

    return Container(
      width: double.infinity,
