    Map<String, Map<String, dynamic>> monthlyStats = {
      'January': {
        'totalBookings': 28,
        'confirmed': 15,
        'pending': 5,
        'cancelled': 3,
        'completed': 5,
        'revenue': 4250000,
        'occupancy': 62.5,
      },
      'February': {
        'totalBookings': 32,
        'confirmed': 18,
        'pending': 6,
        'cancelled': 4,
        'completed': 4,
        'revenue': 4850000,
        'occupancy': 65.3,
      },
      'March': {
        'totalBookings': 30,
        'confirmed': 16,
        'pending': 5,
        'cancelled': 3,
        'completed': 6,
        'revenue': 4650000,
        'occupancy': 63.8,
      },
    };

    Map<String, dynamic> selectedStats =
        monthlyStats[_selectedMonth] ??
            {
              'totalBookings': 0,
              'confirmed': 0,
              'pending': 0,
              'cancelled': 0,
              'completed': 0,
              'revenue': 0,
              'occupancy': 0,
            };

    return Container(
      width: double.infinity,
      padding: EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: cardBg,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: borderColor),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                'Monthly Statistics ($_selectedMonth)',
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.w800,
                  color: darkText,
                ),
              ),
              Container(
                padding: EdgeInsets.symmetric(horizontal: 2, vertical: 2),
                decoration: BoxDecoration(
                  color: primaryColor.withOpacity(0.1),
                  borderRadius: BorderRadius.circular(20),
                ),
                child: DropdownButtonHideUnderline(
                  child: DropdownButton<String>(
                    value: _selectedMonth,
                    icon: Icon(Icons.arrow_drop_down, color: primaryColor),
                    items: _months.map((month) {
                      return DropdownMenuItem(
                        value: month,
                        child: Text(month, style: TextStyle(fontSize: 12)),
                      );
                    }).toList(),
                    onChanged: (value) {
                      setState(() {
                        _selectedMonth = value!;
                      });
                    },
                  ),
                ),
              ),
            ],
          ),

          SizedBox(height: 20),

          GridView.count(
            shrinkWrap: true,
            physics: NeverScrollableScrollPhysics(),
            crossAxisCount: 2,
            crossAxisSpacing: 12,
            mainAxisSpacing: 12,
            childAspectRatio: 1.0,
            children: [
              _buildStatCard(
                title: 'Total Bookings',
                value: selectedStats['totalBookings'].toString(),
                change: '+5%',
                isPositive: true,
                icon: Icons.calendar_month_rounded,
              ),
              _buildStatCard(
                title: 'Revenue (USD)',
                value:
                '\$${(selectedStats['revenue'] / 1000000).toStringAsFixed(1)}M',
                change: '+7%',
                isPositive: true,
                icon: Icons.currency_exchange,
              ),
              _buildStatCard(
                title: 'Occupancy Rate',
                value: '${selectedStats['occupancy']}%',
                change: '+3%',
                isPositive: true,
                icon: Icons.bar_chart_rounded,
              ),
              _buildStatCard(
                title: 'Cancellation',
                value:
                '${((selectedStats['cancelled'] / selectedStats['totalBookings']) * 100).toStringAsFixed(1)}%',
                change: '-0.3%',
                isPositive: false,
                icon: Icons.cancel_rounded,
              ),
            ],
          ),

          SizedBox(height: 20),

          Text(
            'Booking Status Breakdown',
            style: TextStyle(
              fontSize: 16,
              fontWeight: FontWeight.w700,
              color: darkText,
            ),
          ),
          SizedBox(height: 12),

          ..._bookingStatuses.map((status) {
            int count = selectedStats[status.toLowerCase()] ?? 0;
            double percentage = selectedStats['totalBookings'] > 0
                ? (count / selectedStats['totalBookings']) * 100
                : 0;
            Color statusColor = _getStatusColor(status);

            return Container(
              margin: EdgeInsets.only(bottom: 10),
              child: Column(
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Row(
                        children: [
                          Container(
                            width: 12,
                            height: 12,
                            decoration: BoxDecoration(
                              color: statusColor,
                              shape: BoxShape.circle,
                            ),
                          ),
                          SizedBox(width: 10),
                          Text(
                            status,
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w600,
                              color: darkText,
                            ),
                          ),
                        ],
                      ),
                      Text(
                        '$count (${percentage.toStringAsFixed(1)}%)',
                        style: TextStyle(
                          fontSize: 14,
                          fontWeight: FontWeight.w700,
                          color: statusColor,
                        ),
                      ),
                    ],
                  ),
                  SizedBox(height: 8),
                  LinearProgressIndicator(
                    value: selectedStats['totalBookings'] > 0 ? count / selectedStats['totalBookings'] : 0,
                    backgroundColor: borderColor,
                    color: statusColor,
                    minHeight: 6,
                    borderRadius: BorderRadius.circular(3),
                  ),
                ],
              ),
            );
          }).toList(),
        ],
      ),
    );
  }

  Widget _buildStatCard({
    required String title,
    required String value,
    String? subValue,
    required String change,
    required bool isPositive,
    required IconData icon,
  }) {
    return Container(
      padding: EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: bgColor,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: borderColor),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Container(
                width: 36,
                height: 36,
                decoration: BoxDecoration(
                  color: primaryColor.withOpacity(0.1),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Center(
                  child: Icon(icon, size: 20, color: primaryColor),
                ),
              ),
              Container(
                padding: EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                decoration: BoxDecoration(
                  color: isPositive
                      ? successColor.withOpacity(0.1)
                      : dangerColor.withOpacity(0.1),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Row(
                  children: [
                    Icon(
                      isPositive
                          ? Icons.arrow_upward_rounded
                          : Icons.arrow_downward_rounded,
                      size: 12,
                      color: isPositive ? successColor : dangerColor,
                    ),
                    SizedBox(width: 4),
                    Text(
                      change,
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w700,
                        color: isPositive ? successColor : dangerColor,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          SizedBox(height: 12),

          Text(
            value,
            style: TextStyle(
              fontSize: 20,
              fontWeight: FontWeight.w800,
              color: darkText,
            ),
          ),

          if (subValue != null && subValue.isNotEmpty) ...[
            SizedBox(height: 2),
            Text(
              subValue,
              style: TextStyle(
                fontSize: 11,
                color: lightText,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
          SizedBox(height: 4),
          Text(title, style: TextStyle(fontSize: 12, color: lightText)),
        ],
      ),
    );
  }

  Color _getStatusColor(String status) {
    switch (status) {
      case 'Confirmed':
        return successColor;
      case 'Pending':
        return warningColor;
      case 'Cancelled':
        return dangerColor;
      case 'Completed':
        return secondaryColor;
      default:
        return primaryColor;
    }
  }

