      'March': {
        'totalBookings': 45,
        'confirmed': 24,
        'pending': 8,
        'cancelled': 4,
        'completed': 9,
        'revenue': 5250000,
        'occupancy': 70.8,
      },
    };

    Map<String, dynamic> selectedStats =
        monthlyStats[_selectedMonth] ??
            {
