  ListTile _buildDrawerItem(IconData icon, String title, int index) {
    return ListTile(
      leading: Container(
        width: 36,
        height: 36,
        decoration: BoxDecoration(
          color: _selectedIndex == index
              ? primaryColor.withOpacity(0.2)
              : Colors.transparent,
          borderRadius: BorderRadius.circular(8),
        ),
        child: Icon(
          icon,
          color: _selectedIndex == index ? primaryColor : darkText,
          size: 20,
        ),
      ),
      title: Text(
        title,
        style: TextStyle(
          color: _selectedIndex == index ? primaryColor : darkText,
          fontWeight: _selectedIndex == index ? FontWeight.w700 : FontWeight.normal,
          fontSize: 14,
        ),
      ),
      trailing: _selectedIndex == index
          ? Container(
        width: 6,
        height: 6,
        decoration: BoxDecoration(
          color: primaryColor,
          shape: BoxShape.circle,
        ),
      )
          : null,
      onTap: () {
        setState(() {
          _selectedIndex = index;
        });
        Navigator.pop(context);
      },
    );
  }

  BottomNavigationBar _buildBottomNavigationBar() {
    return BottomNavigationBar(
      type: BottomNavigationBarType.fixed,
      currentIndex: _selectedIndex,
      selectedItemColor: primaryColor,
      unselectedItemColor: lightText,
      showUnselectedLabels: true,
      elevation: 8,
      backgroundColor: cardBg,
      selectedLabelStyle: TextStyle(fontSize: 11, fontWeight: FontWeight.w700),
      unselectedLabelStyle: TextStyle(fontSize: 11),
      onTap: (index) {
        setState(() {
          _selectedIndex = index;
        });
      },
      items: [
        BottomNavigationBarItem(
          icon: Icon(Icons.dashboard_rounded),
          activeIcon: Container(
            padding: EdgeInsets.all(6),
            decoration: BoxDecoration(
              color: primaryColor.withOpacity(0.1),
              shape: BoxShape.circle,
            ),
            child: Icon(Icons.dashboard_rounded, size: 20),
          ),
          label: 'Dashboard',
        ),
        BottomNavigationBarItem(
          icon: Icon(Icons.meeting_room_rounded),
          activeIcon: Container(
            padding: EdgeInsets.all(6),
            decoration: BoxDecoration(
              color: primaryColor.withOpacity(0.1),
              shape: BoxShape.circle,
            ),
            child: Icon(Icons.meeting_room_rounded, size: 20),
          ),
          label: 'Accommodations',
        ),
        BottomNavigationBarItem(
          icon: Icon(Icons.calendar_month_rounded),
          activeIcon: Container(
            padding: EdgeInsets.all(6),
            decoration: BoxDecoration(
              color: primaryColor.withOpacity(0.1),
              shape: BoxShape.circle,
            ),
            child: Icon(Icons.calendar_month_rounded, size: 20),
          ),
          label: 'Elite Calendar',
        ),
        BottomNavigationBarItem(
          icon: Icon(Icons.analytics_rounded),
          activeIcon: Container(
            padding: EdgeInsets.all(6),
            decoration: BoxDecoration(
              color: primaryColor.withOpacity(0.1),
              shape: BoxShape.circle,
            ),
            child: Icon(Icons.analytics_rounded, size: 20),
          ),
          label: 'Treasury',
        ),
        BottomNavigationBarItem(
          icon: Icon(Icons.person_rounded),
          activeIcon: Container(
            padding: EdgeInsets.all(6),
            decoration: BoxDecoration(
              color: primaryColor.withOpacity(0.1),
              shape: BoxShape.circle,
            ),
            child: Icon(Icons.person_rounded, size: 20),
          ),
          label: 'Profile',
        ),
      ],
    );
  }

  void _addNewRoom() {
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: Text('Add New Accommodation'),
        content: Text('Feature coming soon for Global Elite luxury estates!'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text('OK', style: TextStyle(color: primaryColor)),
          ),
        ],
      ),
    );
  }

  void _showProfile() {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Global Elite profile section coming soon'),
        backgroundColor: primaryColor,
      ),
    );
  }
}





